-- Generated by scripts/chapters.ts from i18n/deDE/content/: edit those, not this file.
-- chapters[faction][piece] = { title, { paragraph, after = quest, before = quest }, ... }
local _, ns = ...
ns.chapters = {
  [529] = {
    start = { title = "Im Licht", { "Kommt herein, kommt herein! Nein, bleibt dort stehen, im Licht, wo ich Euch richtig sehen kann." }, { "Ihr seht aus wie jemand, der eine Waffe schwingen kann und dem noch niemand gesagt hat, wofür. Hier komme ich ins Spiel. Die Dämmerung hat einen einzigen Feind, die Toten, und es kümmert sie nicht im Geringsten, von welchen Lebenden Ihr abstammt. Nehmt unsere Anstecknadel. Was die Geißel bei sich trägt, interessiert mich brennend, und dann werden wir wissen, was Ihr seid." }, { "Noch etwas. Alles auf dieser Welt, das man zu weit treibt, wird sein eigener Feind. Mut. Glaube. Das Licht selbst. Merkt Euch das. Ich werde Euch später danach fragen." } },
    friendly = { title = "Abzeichen", { "Ihr treibt Euch nun lange genug in den Pestländern herum, dass wir offen miteinander reden können." }, { "Wisst Ihr, was sie bei sich tragen, die Toten? Abzeichen. Die Geißel ist ein Heer, und ein Heer hat Ränge, selbst wenn seine Soldaten tot sind. Die gewöhnlichen Steine zeichnen das Fußvolk aus. Die selteneren die Elite. Die seltensten gehören den Herren, den Kreaturen, die die Befehle geben, und sie sind weit mehr wert als der Rest. Ich führe die Zählung. In manchen Nächten ist sie der einzige Beweis, den ich habe, dass wir gewinnen." }, { "Jedes Bündel Abzeichen, das man mir bringt, bringt eine Marke ein. Irgendwo in den Pestländern hat ein Ding, das einst Befehle befolgte, damit aufgehört. Das finde ich sehr befriedigend. Ich vermute, das sagt etwas über mich aus, und ich habe nicht die Absicht herauszufinden, was." } },
    honored = { title = "Ein Rückgrat aus Eisen", { "Ich habe versprochen, Euch nach dem Übermaß zu fragen. Hier ist meine Frage. Wie nennt Ihr einen Mann, der gegen die Geißel kämpft, zum Licht betet und Unschuldige tötet, weil er sich nicht die Mühe macht, sie von den Schuldigen zu unterscheiden? Der Scharlachrote Kreuzzug nennt ihn einen Kreuzritter. Ich nenne ihn einen Gotteslästerer!" }, { "Sie halten einen Teil von Stratholme. Darin hütet ein Mann namens Galford ihr Archiv, Jahre dessen, was sie Erkenntnisse zu nennen belieben." }, { "Ich will, dass es brennt. Ich will ihn tot sehen. Sagt mir, das sei unvernünftig. Nur zu.", before = 5251 }, { "Ihr habt es für mich verbrannt, und in jener Nacht habe ich besser geschlafen als seit Jahren. Sagt mir, das sei unvernünftig gewesen. Nur zu.", after = 5251 }, { "Seht Ihr, wir von der Dämmerung sind duldsam. Duldsamkeit ist keine Weichheit. Sie braucht ein Rückgrat aus Eisen, sonst biegt sie der erste Eiferer, der des Weges kommt, in zwei Hälften. Ich habe ein Rückgrat aus Eisen." } },
    revered = { title = "Die zurückkommen", { "Euch wird aufgefallen sein, dass ich immer hier bin, wenn Ihr zurückkehrt. Ich schicke Leute los. Das ist meine Aufgabe. Ich schicke Leute wie Euch nach Stratholme und auf die toten Felder, und ich warte in der Kapelle des Hoffnungsvollen Lichts und zähle, was zurückkommt, die Steine und die Leute. Die Steine kommen immer zurück." }, { "Also führe ich zwei Zählungen. Die Steine kommen ins Hauptbuch, wo die Rüstmeister sie sehen können. Die andere Zählung schreibe ich nirgendwo auf, und ich könnte Euch jede Zeile davon aufsagen." }, { "Euch wird auch aufgefallen sein, dass ich das Fußvolk der Geißel niemals schwach nenne. Warum, habe ich von denen gelernt, die nicht zurückgekommen sind." }, { "Naxxramas ist dort oben, die Zitadelle Kel'Thuzads, und die Dämmerung wird Leute hineinschicken. Manche von ihnen werden Leute sein, die ich zuvor schon anderswohin geschickt habe." }, { "Und Ihr habt mir den Kopf eines Dämons aus Stratholme gebracht, und ich habe noch nicht entschieden, was er bedeutet. Diese Leute in Rot glaubten, dem Licht zu dienen. Sie dienten einem Schreckenslord. Ich nannte sie Gotteslästerer. Ich wüsste gern, wie ich sie jetzt nennen soll.", after = 5262 } },
    aside = { title = "Beiseite", { "Ihr kommt immer noch zurück. Es überrascht mich nicht mehr, und das, ich warne Euch, ist der erste Schritt dazu, mich darauf zu verlassen." } },
    exalted = { title = "Champion", { "Champion." }, { "Kniet nieder. Nein, kniet nicht. Ich bin kein König, und Ihr würdet nur mit diesem Gesichtsausdruck wieder aufstehen." }, { "Ich habe seit Jahren niemanden mehr so genannt. Ich möchte, dass Ihr versteht, dass ich das Wort nicht leichtfertig gebrauche, denn ich gebrauche nichts leichtfertig, wie Euch vielleicht aufgefallen ist." }, { "Ich sagte Euch einmal, dass alles, was man zu weit treibt, sein eigener Feind wird. Seitdem habe ich viel darüber nachgedacht, und das ist Eure Schuld. Ich bin ein Mann, der für das Licht eine Bibliothek verbrennen und den Rauch eine Predigt nennen würde. Wenn in dieser Kapelle jemand Gefahr läuft, zu dem zu werden, was er hasst, $gmein Freund:meine Freundin;, dann seid nicht Ihr es." }, { "Darum brauche ich Euch. Ein Champion ist nicht jemand, der mir zustimmt. Ein Champion ist jemand, dem ich zutraue, mir zu sagen, wann ich zu weit gegangen bin, und dem ich glauben werde. Ich hatte lange keinen mehr." }, { "Der Krieg ist nicht vorbei. Eines Tages wird die Dämmerung gegen den ziehen, der hinter alldem steht, wo immer er sitzt, und an jenem Tag hätte ich Euch gern in meiner Nähe. Nicht vorn. In meiner Nähe." } },
  },
  [576] = {
    start = { title = "Die Tür", { "Ich habe Euch die Straße heraufkommen sehen. Ihr wollt den Tunnel. Fremde wollen immer den Tunnel, weil er kürzer ist als die Berge. Er gehört nicht Euch." }, { "Wir sind die Holzschlunde, der letzte Stamm, den die Verderbnis nicht genommen hat. Die anderen habt Ihr getroffen. Jeder hat sie getroffen, und jeder schießt jetzt zuerst, ohne hinzusehen. Wir auch." }, { "Grazle wird Euch sagen, wie Ihr uns umstimmen könnt. Grazle sagt jedem alles. Tut, worum er bittet, und dann tut es noch einmal." }, { "Ich werde hier sein, an der Tür. Ich habe ein Auge. Für Euch reicht es." } },
    friendly = { title = "Die Zählung", { "Von hier an wird gezählt." }, { "Federn aus dem Kopfputz der Totenwaldfelle, zu Nafien am Tor oder zu Grazle, für die, die sie bringen. Sie sagen mir die Zahl, ob ich frage oder nicht. Ich habe keine Freude daran. Die Totenwaldfelle waren unsere Verwandten, bevor das Teufelszeug in den Teufelswald kam und in sie, und eine Feder sagt nicht, wer von ihnen es war." }, { "Die Perlen sind schlimmer. Die Winterfelle trugen sie gegen böse Geister. Ihr seht, wie gut das ging. Sie trugen ihre Schutzzeichen, das Übel kam trotzdem herein, und nun gehen ihre Perlen in den Taschen von Fremden zu Salfa." }, { "Salfa hält Euch für nützlich, und Salfa irrt sich selten. Ich beobachte Euch trotzdem." } },
    honored = { title = "Was wenige gefragt haben", { "Ihr seid so oft durch die Feste gegangen, dass die Wachen nicht mehr nach etwas greifen, wenn Ihr vorbeikommt. Also hier ist etwas, und Ihr könnt damit tun, was Euresgleichen mit Dingen tut, die man ihnen erzählt." }, { "Die Nachtelfen nahmen einst unsere Hilfe an, gegen die Dämonen, und viele von ihnen nahmen sie mit zugehaltener Nase. Manche haben nicht damit aufgehört. Fragt die Schildwachen, an einem Tag, an dem sie ehrlich sind." }, { "Die Winterfelle waren unsere Freunde, und das ist nicht lange her. Dann begann ihr Oberhäuptling Dinge zu wollen, die niemand verstand, und sein Stamm wandte sich gegen alle in seiner Nähe, uns mit eingeschlossen. Seitdem bleiben wir unter uns. So viel haben wir gelernt." }, { "Euer Volk schreibt seine Geschichte auf. Wir nicht. Und was uns am teuersten ist, daran seid Ihr hundertmal vorbeigegangen, ohne es zu sehen. Noch nicht." } },
    revered = { title = "Einmal gesagt", { "Ich sage das nur einmal, und Ihr werdet es Grazle nicht weitererzählen." }, { "Wir können diesen Ort nicht allein verteidigen. Salfa sagt das Fremden, weil Salfa ehrlich ist bis zum Übermaß. Ich sage es Euch, weil... Nein. Ich sage es dir, weil du $gkein Fremder:keine Fremde; mehr bist, und das hätte ich dieses Jahr nicht zu sagen erwartet. Kämen die Winterfelle und die Totenwaldfelle zugleich von zwei Seiten über uns, bräuchten wir jeden Freund, den wir haben, und es sind nicht viele." }, { "Die Könige deines Volkes haben schon früher Botschaft an diese Feste geschickt. Der Zwergenkönig unter seinem Berg. Der Kriegshäuptling der Orcs, in Durotar. Sie wollten reden. Es gab keinen Frieden. Ich könnte dir die Gründe nennen, aber sie würden dir nicht gefallen, und die meisten hätten mit deinem Volk zu tun." }, { "Du bist Ehrfürchtig bei uns. Hier bedeutet das Wort etwas Schlichteres als bei euch. Es bedeutet, dass jemand herauskäme, um dich zu holen, wenn du an der Tür fielest. Ich wäre es. Ich würde den ganzen Weg über schimpfen." } },
    aside = { title = "Beiseite", { "Immer noch hier. Ich zähle immer noch. Salfa sagt, du bist auf halbem Weg zu etwas. Salfa sagt gern solche Dinge. Wenn du angekommen bist, wirst du es von mir hören." } },
    exalted = { title = "Geh langsamer", { "Geh von nun an langsamer durch die Feste. Du wirst es tun, sobald du weißt, warum." }, { "Du hältst diesen Ort für eine Straße. Eine gute Straße, raus aus dem Schnee, mit Furbolgs darin, die gelernt haben, nicht auf dich zu schießen. Es war nie eine Straße. Die Feste wurde für Ursoc und Ursol gemacht, die Bärenzwillinge, die wir ehren, und jeder Tunnel, durch den du geeilt bist, um dir einen Berg zu ersparen, gehört dazu. Wir lassen die, denen wir vertrauen, durch einen heiligen Ort gehen. Die meisten wussten nie, was er war. Jetzt weißt du es." }, { "Du wirst nach dem Auge fragen. Jeder, der so weit kommt, fragt nach dem Auge. Nein." }, { "Ich war der Letzte in dieser Feste, der dir vertraut hat, und ich möchte, dass man sich daran erinnert, denn ich hatte recht, langsam zu sein. Vertrauen, das leicht kommt, geht auf demselben Weg. Meines kam auf dem langsamen Weg, und es geht nirgendwohin." }, { "Da ist noch etwas, und wir geben es nicht vielen. In einer schlimmen Stunde, weit von hier, wird einer unserer Ahnen kommen und an deiner Seite stehen und dich heilen, während er kämpft. Nicht für kleine Stunden. Sie sind alt, und sie gehören uns, und sie kommen mir zuliebe.", after = 8481 } },
  },
  [59] = {
    start = { title = "Insekten", { "Ein Insekt. An meinem Tisch. Es spricht mit mir." }, { "Wir machen keine Geschäfte mit Insekten, und ich habe keine Geduld für sie. Ihr habt nichts, was ich will, Ihr wisst nichts, was ich brauche, und Ihr versperrt mir den Blick auf die Tür. Die Bruderschaft hat dem Imperator vor langer Zeit den Rücken gekehrt. Ich trinke immer noch in seiner Stadt. Beides geht Euch nichts an." }, { "Die Bruderschaft unterhält ein Haus in der Thoriumspitze für Streuner, wo man freundlicher ist. Seid dort zuerst ein Streuner. Sollten sie je Euren Namen lernen, kommt wieder, und ich werde erwägen, ihn ebenfalls zu lernen." }, { "Bis dahin, fort. Fort." } },
    friendly = { title = "Bedingungen", { "Die Thoriumspitze kennt Euren Namen. Nun denn. Stellt Euch dorthin, wo ich Euch sehen kann, und hört die Bedingungen." }, { "Wir stiegen einst hinab in die Hallen des Feuerlords, für seine Kerne und sein Leder und das Blut des Berges, das seine eigenen Tränen sind. Viele von uns stiegen hinab und kamen nicht wieder herauf. Jetzt geht Ihr. Ihr seid billiger. Nichts Persönliches. Bei TB Ltd. ist nie etwas persönlich." }, { "Gunst öffnet die Bücher der Bruderschaft, die Pläne und Muster, die Euch sonst niemand auf dieser Welt verkaufen wird. Sie ist die einzige Münze, die ich annehme, die nicht anläuft. Gold kann ich von jedem haben." }, { "Die Gabe wird gewogen. Die Gabe wird für ausreichend befunden. Lasst es Euch nicht zu Kopf steigen." } },
    honored = { title = "Das kleine Messer", { "Die Bruderschaft empfängt Euch und würdigt Euer... ach, setzt Euch, wenn Ihr wollt. Niemand setzt sich zu mir. Daran erkennt Ihr, dass es eine Ehre ist." }, { "Ihr haltet uns für Dunkeleisenzwerge, denen ein Gewissen gewachsen ist. Die Hälfte davon stimmt. Wir waren eine Gilde, bevor wir irgendetwas anderes waren, eine Handwerkergilde in Ironforge, als es noch ein einziges Ironforge gab und die Clans noch nicht darum in den Krieg gezogen waren. Eine ängstliche Gilde. Wir waren sicher, dass unsere Rivalen Geheimnisse kannten, die wir nicht kannten. Also beschafften wir uns ihre besten Werke und nahmen sie auseinander, um nachzusehen. So fanden wir die Verzauberkunst. Nicht durch Studium. Durch Diebstahl, und Geduld, und ein sehr kleines Messer." }, { "Als der Krieg kam und die Clans Seiten wählten, wählten wir. Ihr wisst, welche. Ich werde mich dafür bei keinem Fremden entschuldigen, und ich bin noch dabei zu entscheiden, was Ihr seid, also entschuldige ich mich auch bei Euch nicht." }, { "Unser bestes Geheimnis haben wir zuerst gestohlen." } },
    revered = { title = "Die Verschwendung", { "Die Bruderschaft wird Eure Frage anhören. Nein. Ich werde es." }, { "Ihr wollt wissen, warum wir gegangen sind. Nicht die kurze Fassung." }, { "Als der Feuerlord erwachte, gehörte der Berg ihm, und wir ebenso. Das Volk des Imperators wurde zu seinen Dienern, und die Bruderschaft zu seinen Schmieden. Wir arbeiteten an seinen Essen. Wir fertigten seine Waffen, dieselbe Klinge immer und immer wieder, für ein Heer, dem es gleich war, wie gut ein Ding gemacht war. Versteht mich recht. Es war nicht die Grausamkeit. Zwerge können Grausamkeit ertragen. Es war die Verschwendung. Die feinsten Hände unter dem Berg, die dasselbe Schwert hämmerten, für Kreaturen, die es nicht von einem schlechteren unterscheiden konnten." }, { "Mein Lehrling fand den Weg hinaus. Oilfist. Heute Aufseher Oilfist, in der Thoriumspitze, der den Ort führt wie eine Garnison. Er plante es unter der Nase der Aufseher, und wir fertigten, was wir brauchten, um aus den Tiefen hinauszugehen. Die meisten, die frei kamen, liefen, so weit ihre Beine sie trugen. Wir blieben auf der anderen Seite der Schlucht stehen. Die Rohstoffe sind hier. Handwerk läuft nicht davon." }, { "Und warum ich hier bin, an einem Tisch in der Stadt des Imperators selbst? Das Bier. Nächste Frage." } },
    aside = { title = "Beiseite", { "Ihr schon wieder. Setzt Euch. Nein, nicht dort. Dort. Ihr habt Euch den besseren Stuhl verdient, und es ist derselbe Stuhl, aber ich werde es wissen." } },
    exalted = { title = "Partner", { "Schluss mit den Förmlichkeiten. Du und ich, wir sind über das Wiegen von Gaben hinaus. Hör zu, ganz schlicht, denn so rede ich jetzt nur noch mit dir." }, { "Die Bruderschaft hütet das Geheimnis des Hammers des Feuerlords. Sulfuras. Der große Hammer, den er dort unten im Kern trägt. Wir können einen Schmied lehren, den Sulfuronhammer zu schmieden, und mit dem Auge von Sulfuras darin könnte ein Held die Hand von Ragnaros hinaus in die Welt tragen. Denk darüber nach, was das bedeutet. Wir haben ein Zeitalter lang Waffen für ihn gefertigt. Jetzt verkaufen wir das Schmieden seiner eigenen an jeden, der stark genug ist, ihn zu töten, zu einem fairen Preis. Ich war in meinem ganzen Leben noch nie so zufrieden mit einem Geschäft." }, { "Ich verliere dabei den Kopf. Leg mir einen Sulfuronblock hin, und ich werde schreien. Ich weiß. Es ist mir gleich." }, { "Und hier das andere, da du über die Schwelle bist. Eine Gilde wie unsere lebt nicht vom Handwerk allein. Wenn ein Rivale zu gut wird, hat seine Esse dann und wann einen Unfall. Wir sind nie auch nur in der Nähe. Du wirst dich erinnern, dass wir nie auch nur in der Nähe sind." }, { "Du kamst als Insekt an meinen Tisch. Du verlässt ihn als $gPartner:Partnerin;. Lies deine Verträge, alle. Meine ganz besonders." } },
  },
  [609] = {
    start = { title = "Der andere Feind", { "Willkommen in der Burg! Alle hier beobachten die Käfer. Sie sind groß, es gibt sehr viele von ihnen, und sie sitzen in ihren Stöcken und hinter dieser Mauer, als ob sie auf etwas warten, also nehme ich es keinem übel, dass er sie beobachtet." }, { "Aber dreh dich um. Die Kultisten draußen in der Wüste warten nicht. Sie bauen und rufen und reichen sich Zettel voller Gekritzel weiter. Mein großer Bruder Huum und ich bleiben an ihnen dran, weil es jemand tun muss und sonst niemand es tun wird." }, { "Käfer haben wir reichlich. Einen echten Kampf habe ich lieber." } },
    friendly = { title = "Gekritzel", { "Die Papiere des Kults will ich am meisten. Kleine Fetzen voller Gekritzel. So reden ihre Lager miteinander!" }, { "Ich kann sie nicht lesen, und ich muss es auch nicht. Jeder Stapel, den man einem toten Kultisten abnimmt, ist eine Nachricht, die nie ankommt, ein Befehl, den niemand erhält, ein Lager, das auf Nachricht wartet und nichts hört. Das ist auch ein Kampf. Ein leiser, aber ein Kampf." }, { "Huum würde sie lesen wollen. Huum hört auf Dinge, auf das Land, auf die Geister, auf Papiere vermutlich auch. Ich, ich horte sie. Eines Tages wird jemand Kluges sie haben wollen, und bis dahin ist jeder Fetzen in meinem Versteck einer, den der Kult nie zu lesen bekommt." } },
    honored = { title = "Mein großer Bruder", { "Hier. Du hast dir eine Geschichte verdient, und ich habe eine, und sie handelt hauptsächlich von meinem Bruder." }, { "Mein Volk, sage ich immer, tut die Dinge langsam und hört zuerst zu. Huum ist durch und durch einer von meinem Volk. Huum hört zuerst zu. Er sagt, die Geister hier rufen ihn, und der Sand trauert um etwas, für das er jemanden braucht, der es hört." }, { "Ich höre es nicht. Ich habe es versucht, mit aller Kraft, so wie ich alles versuche. Ich stehe, wo er steht, und alles, was ich bekomme, ist Sand in den Ohren. Aber ich glaube ihm. Weil er mein Bruder ist. Weil ich es nie ein einziges Mal geschafft habe, ihm einen Irrtum nachzuweisen. Und weil er, wenn er abends still wird, zu lange still bleibt." }, { "Also kämpfe ich, und er hört zu, und zwischen uns beiden hat die Burg, was sie braucht." } },
    revered = { title = "Was sie herbeirufen", { "Was mich nachts wach hält, ist eine kurze Liste. Sie hält mich wach, also kann sie dich auch wach halten." }, { "Die Kultisten beten dort draußen nicht nur. Sie rufen Dinge aus den Beschwörungssteinen herbei: Templer, dann Fürsten, dann Lords, jeder größer als der letzte und jeder ein größeres Kopfzerbrechen für mich. Und jeder gibt Befehle weiter. Wir wissen, dass man sie zerschlagen kann. Was wir nicht wissen, ist, wem sie gehorchen. Vielleicht betet der Kult sie an. Vielleicht sind sie nur Boten, und was auch immer die Botschaften schickt, hat sich noch nicht gezeigt." }, { "Also, die Liste. Die Käfer in ihren Stöcken und hinter der Mauer. Der Kult in der Wüste. Was auch immer der Kult herbeiruft. Was auch immer Huum abends so still macht. Das sind viele Feinde für ein einziges Stück Sand." }, { "Alle sagen mir, ich soll abwarten und beobachten. Ich warte und beobachte schon lange. Es ist mir nicht ans Herz gewachsen." } },
    aside = { title = "Mein Posten", { "Derselbe Posten, derselbe Sand. Geh und ring für mich mit den Großen, und dann komm zurück und erzähl mir, wie hart sie zuschlagen!" } },
    exalted = { title = "Die größte Truhe", { "Weißt du, was ich dir geben würde, wenn ich dir irgendetwas geben könnte? Meinen Posten. Nur für einen Tag." }, { "Die Truhe taugte als Dankeschön überhaupt nichts. Ich habe dich lachen hören, als du sie geöffnet hast, und ich weiß, dass du nicht über die Truhe gelacht hast.", after = 8352 }, { "Ich würde mit dir aus der Burg gehen, an den Lagern und den Steinen vorbei, hinaus in die Wüste, und wir würden das größte Ding finden, das der Kult herbeirufen kann, und gemeinsam herausfinden, wie hart es zuschlägt!" }, { "Ich kann nicht. Jemand muss hier stehen, und das bin ich. Das war schon immer ich. Also erzähle ich dir stattdessen, was ich noch nie jemandem erzählt habe. Wenn Huum abends still wird, beobachte ich ihn. Ihn, nicht das, worauf er hört. Er ist der, den ich bewache. Die Burg, die Mauer, die Papiere, all das würde ich ohne einen zweiten Gedanken für ihn eintauschen, und das ist etwas Schreckliches, wenn man Wache steht." }, { "Huum würde mir sagen, dass das Land mehr Schutz braucht als er. Huum hätte recht. Das hat er meistens. Ich würde trotzdem ihn wählen." }, { "Du bist $gder Einzige, dem:die Einzige, der; ich es je gesagt habe." } },
  },
  [270] = {
    start = { title = "Noch nicht", { "Willkommen. Man nennt mich Rin'wosho, und ich handle von Zuldazar aus, weit weg von zu Hause und noch weiter weg von meinen besten Kunden." }, { "Ihr werdet sehen wollen, was ich führe. Das wollen alle. Waren der südlichen Meere, Muster für Eure Schneider und Eure Lederer, Früchte, die Ihr nie gekostet habt. Und ich würde sie Euch nur zu gern verkaufen. Aber ich handle nur mit Freunden meines Stammes, und das seid Ihr noch nicht." }, { "Die Zandalar führen Krieg gegen einen Gott, der hätte fortbleiben sollen. Helft ihnen dabei, dann kommt wieder, und wir reden über Preise." } },
    friendly = { title = "Ehre, in Münzen", { "Jetzt können wir Geschäfte machen, $gmein Freund:meine Freundin;." }, { "Bei den Zandalar läuft es so. Was Ihr für den Stamm aus Zul'Gurub herausholt, vergilt der Stamm mit Ehre, in Münzen, die man behält und bei mir ausgibt. Ich mag ein Volk, dessen Dankbarkeit in einen Geldbeutel passt. Gebt sie aus oder behaltet sie, wie es Euch gefällt. Ich habe Leute gekannt, die eine jahrelang aufbewahrten, aus keinem Grund, den sie hätten nennen können." }, { "Die Münzen, die die Trolle jener Stadt bei sich tragen, sind eine andere Sache. Jeder dieser Stämme hat seine eigenen, eine jede schwer von Mojo, und Vinchaxa nimmt sie für den Gebrauch des Stammes entgegen. Um die würde ich nicht feilschen. Manche Dinge sind mehr wert als das, was sie kaufen." } },
    honored = { title = "Die Mango", { "Ihr habt noch nie eine Essenzmango gegessen. Niemand, der eine gekostet hat, fragt, was das ist." }, { "Sie wachsen überall, wo die südlichen Meere einen Strand haben, auf dem sie wachsen können. Eine davon, und Ihr seid erholt, Leib und Gedanken zugleich, als hättet Ihr eine Nacht daheim im Sand geschlafen. Ich halte hier auf der Insel einen Vorrat für die, die der Stamm zu achten gelernt hat. Ich könnte sie hier für ein kleines Vermögen verkaufen. Ich tue es nicht. Manche Früchte sind nur für Freunde." }, { "Ich vermisse Zuldazar nicht wegen seines Königs oder seiner Priester. Ich vermisse es wegen der Früchte, und des Meeres, und meiner eigenen Sprache, gesprochen von Leuten, die keine Angst haben. Hier hat jeder Angst. Man hört es daran, wie leise die Insel spricht, sobald die Sonne untergegangen ist. Hier schmecken selbst die Früchte nach weiter Ferne." } },
    revered = { title = "Was die Priester nahmen", { "Mit Eurem Ansehen kommen meine stärksten Gebräue, die, die Zanza gesegnet hat. Nehmt eines nach dem anderen, $gmein Freund:meine Freundin;. Einen Segen stapelt man nicht." }, { "Hört nun, warum der Stamm seine Segnungen überhaupt Außenstehenden gibt. In Zul'Gurub sind die Hohepriester die Sklaven des Seelenschinders, und durch sie trinkt er unsere Götter. Nicht ihr Blut. Ihre Stärke. Jeden Tag, an dem er diese Stadt beherrscht, werden die ältesten Mächte, die mein Volk kennt, ein wenig schwächer und er ein wenig stärker, und niemand kann mir sagen, wie tief es noch reicht." }, { "Ich schlafe schlecht auf dieser Insel. Ein Händler weiß, was seine Regale verlässt, und ich kann nicht mehr ermessen, was die Götter verlässt. In manchen Nächten gehe ich den Strand entlang und spreche in meiner eigenen Sprache mit dem Meer, damit irgendetwas auf dieser Insel sie noch hört." }, { "Wenn ich Euch also ein gesegnetes Gebräu reiche, ist das keine Großzügigkeit. Das ist Ware, die bewegt wird, bevor das Lagerhaus brennt." } },
    aside = { title = "Stammkunde", { "Eine Mango? Vorsicht. Ein Händler, der denselben Kunden zweimal bedient, gewinnt ihn lieb, und Zuneigung ist sehr schlecht für die Preise." } },
    exalted = { title = "Von zu Hause", { "Diese verkaufe ich an niemanden sonst. Siegel, über das Wasser aus den südlichen Meeren gebracht, für die Schultern derer, die der Stamm zu den Seinen zählt. Macht, Mojo oder Gelassenheit: Ich habe in meinem Leben sehr viele Schultern ausgestattet, und wenige von ihnen trugen etwas, das das Gewicht wert war." }, { "Unter jedem Handel, den wir gemacht haben, liegt eine schlichte Sache. Die Münzen fließen in die Verteidigung des Stammes gegen den Gott in jener Stadt, und die Schmuckstücke werden auf Zanzas Altar zerbrochen, jeder Funke Mojo gegen ihn gewendet. Lange habe ich mir eingeredet, ich würde nur verkaufen. Ich habe vor einiger Zeit aufgehört, es zu glauben. Ich denke, das war ungefähr, als ich anfing, die besten Mangos für Euch zurückzulegen." }, { "Eines Tages werde ich heimkehren, wenn der Seelenschinder Asche ist und unsere Götter wieder heil sind. Das Meer wird noch da sein. Es ist das Einzige, um das ich nie feilschen musste. Am ersten Abend werde ich im Sand eine Mango essen und an diese hässliche kleine Insel denken, und ich vermute, ich werde sie vermissen. Wenn ich gehe, werde ich ihnen von Euch erzählen, und von Euren Geschäften." } },
  },
  [910] = {
    start = { title = "Keiner Beachtung wert", { "Ihr müsst die Stimme nicht senken. Wenig von dem, was Sterbliche sagen, dringt bis zu meinesgleichen vor. Der bronzene Drachenschwarm hat seit sehr langer Zeit keinen von Euch begünstigt, und Ihr beginnt bei uns, wo jeder Sterbliche beginnt, nämlich bei gar nichts." }, { "Nehmt es nicht schwer. Es ist kein Hass. Wir schenken nur langsam unsere Aufmerksamkeit dem, was nicht von Dauer ist." }, { "Dort, hinter den Mauern der Burg, regt sich der Stock. Der Boden um ihn bebt, und der alte Feind rüstet erneut zum Krieg. Darauf zu achten lohnt sich. Darum bin ich hier." } },
    friendly = { title = "Körner", { "Nun denn. Ihr habt begonnen, ein wenig zu zählen. Ich spürte es, wie man ein einzelnes Korn in einer Sanduhr rutschen spürt: kaum, und dann lässt es sich nicht mehr übersehen." }, { "Was der Schwarm von Sterblichen will, ist einfach und sehr schwer. Jeder Diener der Herren der Insekten, der fällt, ist ein Korn, das von ihrer Seite des Glases auf unsere wandert. Ich hüte dieses Glas schon lange. Es ist gut, eine weitere Hand daran zu sehen." }, { "Ein Wort über den bronzenen Drachenschwarm, um das Ihr nicht gebeten habt: Wir eilen nicht. Das ist nicht dasselbe, wie gleichgültig zu sein. Erinnert Euch daran an dem Tag, an dem wir Euch langsam erscheinen." } },
    honored = { title = "Der Atem", { "Ich gebe Euch eine alte Geschichte, wenn Ihr sie nehmen wollt. Ich werde sie ohne Schmuck erzählen." }, { "Ich lag einst im Sterben. Ich hatte nichts mehr zu geben, meine Wunden waren offen, und ich hatte keine Angst mehr, und daran erkannte ich, wie nah das Ende gekommen war. Dann kam der Herr meines Schwarms zu mir." }, { "Ich erinnere mich nicht an den Atem. Ich erinnere mich, dass ich danach nicht mehr im Sterben lag und dass man mir sagte, ich solle bleiben, solange das Bleiben nötig sei. So wurde ich ein Wächter. Ich habe nie ein besseres Wort dafür gefunden als das, das man mir gab." }, { "Es war gütig getan, und es hat mich seither etwas gekostet. Beides ist wahr, und ich habe aufgehört zu versuchen, eines davon kleiner zu machen als das andere." } },
    revered = { title = "Der Eid", { "Vor langer Zeit habe ich einen Eid geschworen, und nun ist endlich die Zeit gekommen, ihn zu halten. Was er war, gehört mir. Wie es sich anfühlt, ihn zu halten, kann ich Euch geben." }, { "Es fühlt sich an wie eine Tür, die man so lange beobachtet hat, dass man vergaß, dass sie sich öffnen kann. Der Stock regt sich, der Sand verschiebt sich, die Qiraji machen sich bereit, und mit einem Mal ist das Warten vorbei, und ich merke, dass ich es nicht wollte. Ein gehaltener Eid ist ein Eid, den man nicht mehr trägt. Ich habe diesen so lange getragen, dass ich mein eigenes Gewicht ohne ihn nicht kenne." }, { "Ein Wächter fürchtet eine Sache, und es ist nicht der Feind. Der Feind ist ehrlich. Was ein Wächter fürchtet, ist der Gedanke, dass der, auf den man wartet, nicht zurückkehren wird, und dass man trotzdem weiter wartet, aus Gewohnheit, lange nachdem es noch etwas bedeutet." }, { "Ich hatte diesen Gedanken jeden Tag, länger, als es Namen für Euresgleichen gibt." } },
    aside = { title = "Die Sanduhr", { "Auf halbem Weg nach Eurer Rechnung. Nach meiner ein Augenblick. Keiner von uns irrt sich. Geht weiter. Das Glas nimmt es nicht übel." } },
    exalted = { title = "Gunst", { "Kein Sterblicher hat seit tausend Jahren die Gunst des bronzenen Drachenschwarms besessen. Früher fragte ich mich, ob je einer es würde, so wie man sich in dieser Wüste Regen wünscht: müßig, aus Gewohnheit, ohne Hoffnung." }, { "Ihr besitzt sie nun. Es bedeutet, dass ich aufhören werde, mit Euch zu sprechen, wie ich mit einem Fremden spreche. Das ist alles, was es bedeutet, und ich finde, es ist sehr viel. Sehr lange war jeder, mit dem ich sprach, ein Fremder, selbst die an meiner Seite, weil ein Teil von mir immer der Mauer zugewandt war." }, { "Ihr seid für mich in die Höhlen der Zeit gegangen und habt den Herrn zurückgekehrt gefunden. Meine Wacht ist vorüber. Ich weiß noch nicht, was ein Wächter tut, wenn das Wachen endet. Bleibt eine Weile und helft mir, es herauszufinden.", after = 8286 }, { "Ich habe lange darauf gewartet, dass etwas ankommt. Ich hätte nicht erwartet, dass Ihr es seid. Mit jemandem an der Seite zu warten ist etwas anderes, und ich hatte vergessen, wie anders. Wenn Ihr zurückkommt, wie spät auch immer, werde ich Euch erkennen. Ich bin froh, mich in den Sterblichen geirrt zu haben. In manchen von ihnen jedenfalls. In einem." } },
  },
  [749] = {
    start = { title = "Ein Handel", { "Ihr wurdet nicht im Wasser geboren, und wofür wir kämpfen, wird Euch immer verschlossen bleiben. Nichts hier wird klarer, wenn man so tut, als wäre es anders." }, { "Ein Handel braucht kein Verständnis. Die Wasserfürsten bekämpfen die Herren der Luft, der Erde und des Feuers, und es ist das Feuer, das wir nicht vergeben können. Ihr seid klein und kurzlebig, und Ihr geht auf Land, das brennt. Ihr habt Eure eigenen Gründe zu wollen, dass das Feuer gelöscht wird. Eure Gründe und unsere mögen eine Weile in dieselbe Richtung fließen. Das gedenke ich zu nutzen." }, { "Erweist Euch als nützlich, und die Tiefe wird sich an Euch erinnern. Sie vergisst fast alles." } },
    friendly = { title = "Reinheit", { "Ihr wart nützlich. Das ist seltener, als Ihr denken würdet, unter Euresgleichen." }, { "Versteht, wofür wir kämpfen. Ihr steht jetzt an unserer Seite. Was uns stark macht, ist, dass wir rein sind. Wasser, das aufnimmt, was immer es berührt, ist kein Wasser mehr, nur eine Krankheit, die fließt. Als die Seuche Lordaerons in die Elementare drang, die wir dorthin geschickt hatten, kränkte mich, was aus ihnen geworden war." }, { "Über eine Sache weiß ich nichts. Unsere Feinde der Luft und der Erde hüten im Süden Gegenstände der Macht, fern von den Sterblichen, und ich kann Euch nicht sagen, warum. Ich weiß nur, dass ich lieber hätte, sie täten es nicht, was immer sie dort bewahren." } },
    honored = { title = "Die Beratung", { "In unseren Kammern sprach man über Euch, und ausführlich. Das ist nicht unsere Art. Ihr wart der Gegenstand, nicht der Richter, und es ist recht, dass Ihr hört, wie es verlief." }, { "Manche unter uns hielten Euch für ein armseliges Ding, um es an unseren Krieg zu verschwenden, ein Geschöpf, in das wir Kraft gießen würden, nur damit es zerbricht. Sie irrten sich nicht, und sie irren sich auch jetzt nicht. Ihr seid klein. Ihr zerbrecht. Ihr kamt trotzdem zurück, gegen unsere Feinde, wieder und wieder, und jede Rückkehr machte es ihnen ein wenig schwerer, an ihrer Ansicht festzuhalten." }, { "Keiner von uns hielt es für möglich. Die Wasserfürsten achten Euch nun. Es stört die Ordnung der Dinge auf eine Weise, für die ich kein Wort habe, denn ein kleines Ding sollte nicht so viel wiegen, und Ihr tut es. Die Zweifler sind still geworden, so wie eine Strömung still wird, bevor sie sich wendet." } },
    revered = { title = "Der Verlust, für wert befunden", { "Das Wasser kennt weder Gnade noch Bosheit. Ich werde sprechen, wie es spricht." }, { "Es kostet uns, eine Hand zu verlieren, die sich bewährt hat, und das habt Ihr. Einen von Euch gegen die eigenen Hauptmänner des Feuerlords zu schicken, ist das Schwerste, was wir verlangen, und wir verlangen es nur, wenn der Gewinn den Verlust wert befunden wird. Dieses Urteil ist das höchste Lob, das die Wasserfürsten zu zollen wissen. Ich würde es Euch nicht verübeln, wenn Ihr es nicht als solches hört. Wir haben schon früher Agenten verbraucht, und das Wasser schloss sich über ihnen. Über Euch würde es sich nicht so schnell schließen." }, { "Unter dem Berg ist der Boden von Feuerrunen durchzogen. Jede ist eine Tür zu seinem Reich, und jede nährt es. Wenn eine Rune erlischt, schließt sich eine Tür, das Feuer zieht ein wenig weniger aus seiner Heimat, und es ist ein wenig mehr allein auf der Welt. Mehr wollen wir nicht von ihm: dass es allein sei, und dann, dass es fort sei." } },
    aside = { title = "Die Gezeiten", { "Die Gezeiten haben sich ein wenig zu unseren Gunsten gewendet, und manches davon ist Euer Werk. Ein wenig. Es sind große Gezeiten, und Ihr seid ein kleines Geschöpf, und doch haben sie sich bewegt." } },
    exalted = { title = "Legende", { "Dankbarkeit ist eine Gewohnheit der Sterblichen. Unter uns schuldet man nichts für gut getane Arbeit. Die Strömung tut ihre Arbeit, und niemand lobt sie dafür. Das Meer dankt dem Fluss nicht dafür, dass er ankommt." }, { "Ihr habt für uns mit einer Beständigkeit gekämpft, die ich einem Geschöpf Eurer Größe nicht zugetraut hätte, und ich will Euch etwas geben. Ich versuchte mir vorzustellen, was einer von Euch wollen würde, und konnte es nicht. Also gebe ich Euch, was wir wollen würden, wenn wir etwas wollten. Es ist das, was einem Dank bei uns am nächsten kommt, und man sagt mir, unter Euresgleichen sei es Brauch, das laut auszusprechen, also habe ich es getan. Nehmt sie also: eine Quelle unserer Quintessenz, die nicht versiegen wird. Ich setze keine Frist." }, { "Ihr habt mir die Hände der Hauptmänner des Feuerlords gebracht. Die Kunde davon lief wie eine Strömung durch unsere tiefen Hallen. Ich räumte einst ein, Ihr könntet hier als Legende enden. Ich war vorsichtig. Ihr seid bereits eine.", after = 6824 }, { "Ihr seid klein, und Ihr werdet nicht von Dauer sein. Ich denke beides noch immer. Die Tiefe vergisst fast alles. Sie hat beschlossen, Euch zu behalten." } },
  },
  [809] = {
    start = { title = "Wer wart Ihr gleich", { "Ah. Ein Besucher. Wie neuartig. Nein, sagt mir nicht Euren Namen. Ich müsste ihn nur wieder vergessen, und das ist so mühsam, und der Katalog führt sich nicht von selbst." }, { "Wenn man zehntausend Jahre lang das Verzeichnis eines Hauses geführt hat, wird die Stunde eines Sterblichen sehr klein, und Eure Sorgen, welche es auch seien, schrumpfen mit ihr. Ich sage das ohne Bosheit. Ich sage das meiste ohne Bosheit. Es spart Zeit." }, { "Jeder Band in diesen Hallen trägt das Siegel des Hauses, und viel zu viele von ihnen sind nicht dort, wo sie hingehören. Bringt einen zurück, und ich beginne vielleicht, mich an Euch zu erinnern." } },
    friendly = { title = "Kunststückchen", { "Die Folianten also. Die will ich von Euch." }, { "Vor einigen Jahren kam ein Elf aus Quel'Thalas zu uns, Meister Winthalus, auf der Flucht vor dem Untergang seiner Heimat, mit ein paar alten Schätzen. Die verlegte er dann mit einer Sorglosigkeit in diesen Hallen, die ich nur heldenhaft nennen kann. Jeder Foliant enthält einen kleinen Zauber für Eure Ausrüstung. Kunststückchen. Trotzdem, bringt mir einen mit den Reagenzien, die er verlangt, und ich fertige Euch sein Arkanum, und Ihr dürft es tragen und Euch einen Nachmittag lang ein ganz klein wenig weniger sterblich fühlen." }, { "Missversteht meinen Ton nicht. Die Folianten langweilen mich, und ich will jeden einzelnen zurück. Nichts Geschriebenes ist wertlos. Es ist der eine Glaube, den ich in all meinen Jahren unversehrt bewahrt habe, und ich wäre Euch dankbar, ihn nicht auf die Probe zu stellen." }, { "Wer wart Ihr gleich? Es fällt mir gleich ein." } },
    honored = { title = "Das Haus", { "Ihr besteht darauf, mir zwischen den Füßen herumzulaufen, also könnt Ihr ebenso gut das Haus kennen, durch das Ihr geht." }, { "Meister Winthalus schluchzte über einen verlorenen Folianten. Schluchzte. Über einen Schutzspruch. Ich selbst habe um ein verlorenes Buch geweint. Der Verlust dessen, was man wusste, ist der einzige Kummer, den ich achte. Aber man weint um eine Geschichte, nicht um ein Kunststückchen." }, { "Der Prinz ließ ihn häuten. Ich nannte es damals einen Gefallen, und ich hatte lange Zeit, mich zu fragen, ob ich es so meinte. Das sagt Euch etwas über dieses Haus, oder über mich, und ich möchte lieber nicht näher hinsehen." }, { "Dann ist da Azj'Tordin, der vor dem Prinzen floh, und ein Wichtel erleichterte ihn auf dem Weg hinaus um sein Zauberbuch. Er wird nun sterben, wie jeder von Euch. Und wofür? Für etwas frische Luft und sehr viele Bäume." }, { "Ihr seid immer noch hier. Wie seltsam. Die meisten Besucher haben inzwischen den Verstand zu gehen." } },
    revered = { title = "Das Verzeichnis", { "Das Verzeichnis dient einem Zweck. Niemand hat mich seit sehr langer Zeit gefragt, welchem." }, { "Alles, was dieses Haus wusste, seit vor dem Zerbrechen der Welt, ist irgendwo in diesen Hallen niedergeschrieben, und ich weiß, wo. Jeder Krieg, jeder Zauber, jeder törichte Prinz, jeder Name. Ich führe das Verzeichnis, damit, falls die Shen'dralar eines Tages fort sind, und ich vermute, dieser Tag ist näher, als der Prinz glaubt, das, was wir wussten, nicht mit uns geht. Der Prinz sagt gern, er halte das Haus am Leben. Ich bewahre, was es wusste. Von beidem wird meines länger bestehen." }, { "Das Athenaeum ist gewaltig, und das ist das Geringste daran. Es wartet, auf Leser, die nie kommen. Bringt mir einen unserer Bände zurück, und ich reiße Euch vielleicht eine Seite heraus. Ja, ich, der ich daran festhalte, dass nichts Geschriebenes wertlos ist. Eine Seite in einem Buch, das niemand öffnet, könnte ebenso gut ein Möbelstück sein. Lieber verliere ich eine Seite an einen Leser als ein Buch an den Staub. Ein Sterblicher, der eine Seite von hier hinausträgt, kommt vielleicht eines Tages wegen des Rests zurück." } },
    aside = { title = "So bald zurück", { "So bald zurück? Ich hatte Eure Stunde beiseitegelegt, zwischen zwei sehr öden Abhandlungen. Deutet nichts hinein." } },
    exalted = { title = "Euer Name", { "Ich kenne Euren Namen." }, { "Frohlockt nicht. Es ist der erste sterbliche Name seit einem Zeitalter, den zu behalten ich mir die Mühe gemacht habe, und ich habe ihn abgelegt. Für mich kommt das der Zuneigung so nah wie nur möglich. Ich habe ihn an einer vornehmen Stelle abgelegt. Ihr würdet nicht glauben, in welcher Gesellschaft. Generäle, Dichter und eine sehr ermüdende Königin." }, { "Der Eintrag ist kurz. Euer Name, und darunter eine Notiz von meiner eigenen Hand. Sie begann als ein einziges Wort, \"beharrlich\". Später fügte ich \"nützlich\" hinzu, und dann, nach einem langen Streit mit mir selbst, \"willkommen\". Dieses letzte Wort strich ich einmal durch. Es kam zurück, und ich habe es stehen lassen." }, { "Ihr habt mir die stumpfe alte Klinge zurückgebracht, und ich sagte Euch, was es bräuchte, um ihr die Schneide wiederzugeben, samt Drache. Ich rechnete damit, keinen von Euch beiden je wiederzusehen. Ich irrte mich, in Euch zumindest, und ich irre mich selten, und auch das habe ich aufgeschrieben.", after = 7508 }, { "Ich habe fast alles gelesen, was dieses Haus je niedergeschrieben hat. Sehr wenig davon hat mich überrascht, und nichts davon in letzter Zeit. Ihr schon, ein wenig, und mehr als einmal. Geht und tut etwas, das es wert ist, hinzugefügt zu werden. Ich werde mit dem Verzeichnis hier sein, unerträglich wie immer, und ich habe nach Eurem Namen Platz gelassen." } },
  },
  [589] = {
    start = { title = "Fleisch", { "Hallo. Nicht viele steigen so weit hinauf, und die es tun, wollen meist einen Säbler." }, { "Ihr könnt am Ende einen haben, aber ich habe nur die Hälfte zu sagen. Eine Säblerin auf diesem Felsen entscheidet selbst, ob sie Euch tragen will, und kein Preis ändert ihre Meinung. Ihr werdet uns beide gewinnen müssen, und die Katzen sind die schwerere Hälfte." }, { "Also fangen wir an, wo jeder junge Säbler anfängt, beim Futter. Sie fressen eine Menge, während sie ausgebildet werden. Die Schimären und die Bären dieser Hügel tragen reichlich Fleisch. Bringt mir welches. Es ist schlichte Arbeit, und sie zählt, und es wird das erste von vielen Malen sein, dass Ihr sie tut." } },
    friendly = { title = "Noch einmal", { "Gutes Fleisch. Die Säbler haben alles gefressen." }, { "Ich werde Euch viele Male um dasselbe bitten, und ich will, dass es jedes Mal gut getan wird. So lernt ein junger Säbler. Die Lektion kommt wieder, bis sie aufhört, eine Lektion zu sein, und einfach zu dem wird, was die Katze ist." }, { "Es gibt jetzt andere Arbeit. Die Furbolgs der Winterfelle sind seltsam geworden. Sie fürchten sich vor allem, und Verängstigte töten, was ihnen in den Weg kommt. Ich habe nie eine Hand gegen sie erhoben, und ich hatte gehofft, es nie zu tun. Aber sie kommen dem Felsen zu nahe, und ich will sie nicht in der Nähe der Jungen. Drängt sie zurück. Die Jungen sollten die Angst nicht so früh lernen." } },
    honored = { title = "Die Königin", { "Unter alldem liegt eine alte Geschichte, und Ihr habt sie Euch verdient." }, { "Vor langer Zeit war die Königin der Säbler in der Gewalt wütender Riesen, und Tyrande Whisperwind befreite sie. Seitdem sind die Frostsäbler Freunde meines Volkes. Die Königin heißt Shy-Rotam. Ich denke jedes Mal an diese Rettung, wenn eine Katze mich an sich heranlässt. Es war eine alte Güte, und die Katzen haben nie aufgehört, sie zu vergelten." }, { "Die Riesen sind nicht fort. Die Frosthagelriesen sind dieselben, und sie sind immer noch nah. Ich bitte Euch, in ihrem Namen gegen sie zu kämpfen. Für mich ist es eine Schuld, und Ihr würdet helfen, sie zu begleichen. Ich würde es nicht von jemandem verlangen, den die Säbler noch anfauchen." }, { "Ich denke jedes Mal besser von Euch, wenn Ihr hier heraufsteigt." } },
    revered = { title = "Das Junge", { "Wenn ein Junges zum ersten Mal zu mir kommt, frisst es nicht aus meiner Hand. Es nimmt das Futter aus dem Schnee, sobald ich zurückgetreten bin, und es faucht, während es frisst. Ich lege das Fleisch jeden Tag hin, ein wenig näher. Eines Tages nimmt es das Fleisch aus meinen Fingern. Ich konnte nie sagen, welcher Tag es sein wird. Ich habe nur gelernt, das Fleisch weiter hinzulegen." }, { "Letzte Nacht ging mir auf, dass ich mit Euch dasselbe getan habe. Das Fleisch, derselbe Botengang immer wieder, die Furbolgs, die Riesen. Jedes Mal ein wenig näher. Ich habe es nicht geplant. Ich kenne keine andere Art, etwas zu lehren." }, { "Die Säbler kennen jetzt Euren Geruch. Wenn Ihr den Pfad heraufkommt, heben die Jungen die Köpfe und legen sie wieder ab. Von einem Säbler ist das eine große Höflichkeit." }, { "Ich hätte fragen sollen, ob es Euch stört. Ihr seid nicht gegangen. Bei einem Jungen ist das die Antwort, und ich habe sie als Eure genommen." } },
    aside = { title = "Auf halbem Weg", { "Auf halbem Weg. Die Jungen heben nicht einmal mehr die Köpfe, wenn Ihr den Pfad heraufkommt. Sie kennen Euren Schritt. Ich habe beim ersten Mal ein ganzes Jahr gebraucht, um so weit zu kommen." } },
    exalted = { title = "Die Säblerin", { "Es gibt eine Säblerin für Euch." }, { "Ich habe sie von klein auf aufgezogen. Von allen brauchte sie am längsten, um aus meiner Hand zu fressen, und danach war sie die Sturste in allem. Ich dachte, Ihr beide würdet einander verstehen. Sie hat mich mehr als einmal gebissen, bevor sie mir vertraute. Euch hat sie überhaupt nicht gebissen. Ich nehme das als Zeichen." }, { "Sie wird Euch tragen, wohin Ihr wollt, bei jedem Wetter. Sie wird still, wenn man sie zu lange von der Kälte fernhält. Gönnt ihr ab und zu den Schnee." }, { "Am ersten Tag sagte ich Euch, dass Ihr uns beide gewinnen müsstet und dass die Katzen die schwerere Hälfte seien. Ich hatte es verkehrt herum. Die Jungen haben lange vor mir ihren Frieden mit Euch geschlossen. Ich habe so lange unter Katzen gelebt, dass ich für einen Menschen länger brauche als für ein Junges. Ihr seid trotzdem immer wiedergekommen, Tag für Tag, so wie ich ihnen das Fleisch hinlege. Es stellt sich heraus, dass ich das Junge war." }, { "Seid sanft beim ersten Mal. Sie hat den Felsen nie verlassen." } },
  },
  [72] = {
    start = { title = "Die Aktion", { "$gFreund:Freundin;! Ja, Ihr. Stormwind braucht Euch, oder vielmehr braucht es Euren Stoff, was beinahe dasselbe ist!" }, { "Unsere Textilvorräte sind auf einen Stand gefallen, der mich offen gesagt beunruhigt. Verbände, Wämser, Decken, jedes einzelne davon beginnt als Stoff, und die Stadt verbraucht ihn schneller, als irgendwer in einer Ratssitzung zugeben würde. Also haben wir eine Aktion. Eine große, vielseitige, gründlich organisierte Aktion, und ich habe die Ehre, sie zu leiten." }, { "Wolle, Seide, was immer Ihr den Banditen auf der Straße abnehmt. Legt es auf den Tisch, und ich kümmere mich um den Rest, $gmein Freund:meine Freundin;! Die Bürger bemerken, wer gibt. Ich auch. Ich führe sehr gute Bücher." } },
    friendly = { title = "Wohin es geht", { "Jedes Stück, das über diesen Tisch gereicht wird, geht irgendwohin, $gmein Freund:meine Freundin;, und ich mache es mir zur Aufgabe zu wissen, wohin. Ins Waisenhaus zum Beispiel, bei der Kathedrale. Dort leben die Kinder von Soldaten. Letzten Winter ging ein guter Teil gespendeter Seide in ihre Decken, und ich fuhr mit dem Karren mit, um die Papiere zu prüfen. Die Hausmutter glich jede Decke mit meiner Liste ab. Dann nahmen die Kinder sie, wickelten sich ein und wurden still, auf eine Weise, wie ich nie einen Rat still bekommen habe." }, { "Man hat mich mehr als einmal gefragt, ob eine Stadt, die Soldaten zu ernähren hat, ihren Stoff für Decken für Waisen ausgeben sollte. Ich sage immer, dass eine Stadt mit Soldaten mehr Waisen hat als jede andere, und dass eine Stadt, die aufhört, für sie auszugeben, vergessen hat, wofür die Soldaten da sind." }, { "Ein Teil dieser Seide war Eure. Das Hauptbuch lügt nie.", after = 7791 } },
    honored = { title = "Die Nähstube", { "$gFreund:Freundin;! Kommt und lernt die Aktion kennen. Die echte, meine ich, nicht die Hauptbücher." }, { "Jeden Abend kommen in einem Hinterzimmer nahe der Kathedrale die Freiwilligen zum Nähen. Witwen der Wache. Lehrlinge aus den Schneiderwerkstätten, die nichts bezahlt bekommen und über Nähte streiten, als würden sie bezahlt. Ein Sergeant im Ruhestand, der mit einer Hand Verbände rollt und dieselben alten Geschichten über das Rotkammgebirge erzählt, von denen alle so tun, als hätten sie sie nie gehört." }, { "Ich führe ihren Plan. Ich verwahre ihr Garn. Ich halte den Frieden zwischen der Witwe, die von links säumt, und dem Lehrling, der von rechts säumt, und das ist die schwierigste Diplomatie dieser Stadt, was auch immer der Rat denkt." }, { "Euer Stoff geht durch ihre Hände. Sie reden übrigens über Euch. \"$gDer große Spender:Die große Spenderin;\", nennt Euch der Sergeant. Ich habe versucht, ihn zu \"$gunser geschätzter Beitragender:unsere geschätzte Beitragende;\" zu berichtigen. Er weigert sich aus Prinzip. Eure Wolle hat in diesem Raum mehr Streit erlebt als der Rat im ganzen Jahr.", after = 7791 } },
    revered = { title = "Der erste Verband", { "Meine Mutter nähte für die Kathedrale, als ich klein war. Sie nahm mich mit, und ich lernte, einen Verband zu rollen, bevor ich meinen eigenen Namen schreiben konnte. Fest am Anfang, locker am Ende, nie verdrehen lassen. Meine Hände tun es noch, wenn ich nervös bin, mit allem, was auf dem Tisch liegt. Ich habe auf diese Weise Ratsprotokolle aufgerollt, und niemand hat sie vermisst." }, { "Sie hat nie etwas geleitet. Sie arbeitete am Ende eines langen Tisches mit einem Korb und tat die Arbeit, und ging nach Hause, und kam am nächsten Tag wieder. Ich leite die Aktion. Ich schreibe die Formulare und führe die Hauptbücher und stehe in Sitzungen auf. In manchen Nächten denke ich, sie würde das alles sehr komisch finden." }, { "Ich führe diesen Tisch, wie sie Verbände rollte. Fest am Anfang, locker am Ende, nie verdrehen lassen. Ich weiß nicht, ob ich den Posten ohne sie überhaupt angenommen hätte, und ich bin sehr froh, dass ich es tat, am meisten an den Tagen, an denen jemand wie Ihr mit vollen Armen durch diese Tür kommt." } },
    aside = { title = "Das Hauptbuch", { "$gFreund:Freundin;, ein neues Tintenfass! Eure Spalte im Hauptbuch hat das alte leer getrunken. Kein Kauf hat mich je mehr gefreut." } },
    exalted = { title = "Das Vorratslager", { "$gFreund:Freundin;, ich habe ein Band. Ein echtes, blaues, sehr feines, vor Jahren aus meinem eigenen Geldbeutel gekauft." }, { "Als ich diesen Posten übernahm, wollte ich das Vorratslager füllen. Jedes Regal, jede Kiste, jeden Winkel des Lagerhauses, voll bis zur Decke, und dieses Band quer über die Tür gebunden. Ich hatte ein Datum im Kopf. Ich hatte eine Rede. Es war eine ausgezeichnete Rede. Sie hatte einen Teil für den Rat, und einen Teil für die Freiwilligen, und eine Pause für den Beifall." }, { "Das Vorratslager wird nie voll sein. Das verstehe ich jetzt. Solange es eine Stadt gibt, wird es Verwundete geben, und solange es Verwundete gibt, geht der Stoff so schnell zur Tür hinaus, wie er hereinkommt. Früher hätte ich das ein Scheitern genannt. Jetzt nenne ich es die Aktion, und ich bin stolz darauf." }, { "Ihr habt das vor mir verstanden. Ihr habt immer weiter Stoff gebracht, für einen Stapel, der nie höher werden würde, und Ihr habt mich nie gefragt, wann er fertig sei." }, { "Also kommt das Band an Euren Arm statt an die Tür, wenn Ihr es wollt, und die Rede kommt in die Schublade. Ich habe sie niemandem vorgelesen, und ich denke, so ist es besser." } },
  },
  [47] = {
    start = { title = "Unter dem Kettenhemd", { "Stoff. In Ironforge. Man sollte meinen, eine Stadt aus Stein und Stahl hätte keine Verwendung dafür. Da irrt Ihr Euch, und Ihr wärt nicht $gder Erste:die Erste;." }, { "Jeder Zwerg im Kettenhemd trägt Wolle darunter, sonst trägt das Kettenhemd den Zwerg. Jeder Bergmann, der verletzt heraufkommt, braucht einen Verband. Jedes Kind, das in diesen Hallen geboren wird, muss gewickelt werden, wie überall. Der Berg hält uns die Kälte vom Leib. Für die Burschen, die draußen Wache stehen, tut er gar nichts." }, { "Was immer Ihr entbehren könnt, verwende ich. Ich danke Euch nicht mit Reden. Ich danke Euch, indem ich jeden Fetzen verwende." } },
    friendly = { title = "Posten im Schnee", { "Stoff kommt an diesen Tisch, und ich schicke ihn hinaus. Meistens die Pässe hinauf." }, { "Dun Morogh ist im Winter ein harter Ort, und wir haben das ganze Jahr Zwerge dort auf Wache, an den Toren und auf den Graten und an den Straßen hinunter ins Tiefland. Ab und zu schreiben sie zurück. Nicht oft, Zwerge sind keine Schreiber. Wenn doch, dann meistens, um nach Socken zu fragen, und ich schicke sie kistenweise, denn Ihr würdet staunen, was Socken für einen Soldaten tun." }, { "Auch die Straßen hinunter, zu den Seen und ins Sumpfland, wo unsere Soldaten die Wege sichern. Nasses Land. Wolle verrottet dort doppelt so schnell, und sie brauchen sie doppelt so dringend." }, { "Ein Zwerg auf einem Grat im Schneesturm braucht Wolle vor allem anderen. Sogar vor Bier, und das habe ich noch keinem Zwerg ins Gesicht gesagt." } },
    honored = { title = "Die Exilanten", { "Als Gnomeregan fiel, kamen die Gnome mit gar nichts den Berg herunter zu uns, und das im Schnee." }, { "Ironforge gab ihnen zuerst seine Decken, noch bevor es ihnen ein Dach gab, und ich war eine von denen, die sie verteilten. Die Lagerräume leerten sich in jenem Winter schneller, als es je ein Überfall geschafft hat. Wir gaben die Wolle von unseren eigenen Betten und die Polsterung aus unseren eigenen Kettenhemden, und manche der alten Soldaten murrten und gaben sie trotzdem." }, { "Ich habe die erste Decke, die ich ausgegeben habe, noch. Ein Gnom brachte sie mir ein Jahr später zurück, gewaschen und gefaltet, mit einem Zettel, auf dem er sich für die Leihgabe bedankte. Ich hatte sie nicht für eine Leihgabe gehalten. Sie liegt in meiner Schublade. In den kalten Nächten hole ich sie heraus." }, { "Ein guter Teil des Stoffs, der über diesen Tisch geht, geht immer noch an sie, und niemand hier sagt ein Wort dagegen. Dafür sorgen die, die in jenem ersten Winter dabei waren." } },
    revered = { title = "Der Schild", { "Steelshield. Stahlschild, heißt das. Ihr werdet Euch gefragt haben." }, { "Meine Familie trug Schilde, und ich trug auch einen, bis ein Hammer der Dunkeleisenzwerge mein Knie fand und anders entschied. Ich kann gehen. In der Schlachtreihe stehen kann ich nicht. Also gaben sie mir diesen Tisch, und ich hasste ihn." }, { "Meinen Frieden damit zu machen war langsame Arbeit. Ein Schild deckt einen Zwerg, und deckt ihn gut, wenn man etwas taugt. Ein Ballen Wolle, auf den richtigen Grat geschickt, deckt einen ganzen Posten. Das habe ich eines Nachts mit einem Hauptbuch und einer Flasche herausgefunden, und seitdem hat es mir nicht leidgetan. Na ja. Nicht oft. In meinem ersten Jahr schickte ich eine Kiste Wolle auf den falschen Grat, und ein Posten fror eine Woche lang. Ich habe nie vergessen, welcher Grat es war. Ich prüfe jetzt jede Kiste zweimal." }, { "Den alten Schild habe ich noch hinter der Tür. Ab und zu nehme ich ihn herunter und poliere ihn und denke an die, neben denen ich stand, und dann hänge ich ihn zurück und gehe Wolle zählen." } },
    aside = { title = "Ein höherer Stapel", { "Euer Stapel im Lagerraum ist jetzt größer als mein Schreiber. Er nimmt es persönlich. Ich habe ihm gesagt, er soll wachsen." } },
    exalted = { title = "Was das Harte am Leben hält", { "Letzte Woche kam ein Bursche vom hohen Grat herunter. Halb erfroren, den Bart voller Eis, heruntergeschickt mit einem Husten, den der Posten nicht kurieren konnte. Er stand an diesem Tisch, tropfte auf mein Hauptbuch und erzählte mir, die Socken seien den ganzen Winter das einzig Warme auf diesem Grat gewesen, jeder Zwerg dort oben habe ein Paar, und er sei gekommen, um es selbst zu sagen, weil sich sonst keiner die Mühe machen würde." }, { "Diese Socken waren Eure Wolle. Ich habe im Hauptbuch nachgesehen, und dann noch einmal, um sicher zu sein. Er ist ein guter Bursche." }, { "Also tat ich etwas, das ich seit Jahren nicht getan habe. Ich nahm den alten Schild hinter der Tür herunter und gab ihn ihm, für den Fall, dass er wieder hinaufgeht. Es ist ein guter Schild. An einer Wand war er verschwendet. Ich werde ihn nicht mehr brauchen. Ich habe diesen Tisch, und hinter diesem Tisch stehen mehr Zwerge, als je hinter einem Schild standen." }, { "Stahl gewinnt Schlachten. Wolle gewinnt den Winter. Das habe ich langsam gelernt, und Ihr habt mir geholfen, es zu lernen, Ballen für Ballen, ohne dass Euch je jemand gesagt hätte, dass Ihr lehrt." }, { "Jetzt aber, der Bursche wartet auf seine Socken. Reicht mir die Kiste." } },
  },
  [69] = {
    start = { title = "Eine leise Bitte", { "Guten Abend. Wenn Ihr mir ein wenig Eurer Zeit schenken würdet." }, { "Mein Volk hat die letzten Jahre damit verbracht, sich an einem Ort ein Zuhause zu bauen, den es zuvor nicht gab. Ein Baum, in den Himmel gewachsen, mit einer Stadt in seinen Zweigen. Ihr mögt ihn bewundern. Die meisten, die herkommen, tun es. Selten fragen sie, was er gekostet hat oder was er immer noch kostet, und ich möchte einen Fremden nicht mit der Rechnung belasten." }, { "Uns fehlt Stoff, bitterlich, und die Zeiten gönnen uns keine Ruhe, um unseren eigenen zu weben. Wenn Ihr etwas entbehren könnt, wäre Darnassus dankbar, und mein Volk bewahrt seine Dankbarkeit lange." } },
    friendly = { title = "Die Schildwachen", { "Der Stoff, der an diesen Tisch kommt, geht nach Süden, über das Wasser, nach Ashenvale." }, { "Die Schildwachen verteidigen dort den Wald gegen die Horde. Die Orcs kommen wegen der Bäume. Die Schildwachen kommen wegen der Orcs. Der Streit ist jung und fühlt sich schon alt an, und jede Jahreszeit braucht er mehr Verbände als die vorige." }, { "Die Schildwachen verlangen nicht viel. Sie sind stolz, und sie bluten lieber, als dass man sieht, wie sie Hilfe brauchen. Also fällt das Bitten Leuten wie mir zu, die in einer stillen Stadt leben und Stoff in einen lauten Wald schicken, und die gar nicht stolz sind, wenn es um die Wunden der Schildwachen geht." }, { "Euer Stoff war auf dem Weg zu ihnen, bevor Ihr die Terrasse verlassen hattet. Ich legte eine Nachricht bei, von wem er kam. Sie werden nicht zurückschreiben. Schildwachen tun das nie. Aber sie werden es wissen.", after = 7792 } },
    honored = { title = "Die Kälte", { "Früher spürten wir die Kälte nicht." }, { "Länger, als irgendein Königreich der Menschen bestanden hat, alterten wir nicht, und wir erkrankten nicht, und der Winter berührte uns nur leicht. Unsere Weber fertigten Stoff für die Schönheit und für nichts sonst. Ein Nachtelf mochte denselben Umhang ein Leben lang tragen, und ein Leben war eine lange Sache." }, { "Das endete im Dritten Krieg. Wir gaben auf, was wir waren, um die Welt zu retten, und wir würden es wieder tun. Aber in jenem Jahr wurden wir sterblich, und seitdem finden wir heraus, was das von einem Körper verlangt. Ein Fieber, das nicht weicht. Ein alter Elf, der an einem Feuer zittert, das einst genügt hätte. Eine Wunde, die sich nicht von selbst schließt." }, { "Also brauchen wir jetzt Stoff wie nie zuvor. Um einander am Leben zu halten. Unsere Weber fertigen jetzt Verbände und Decken und schlichte warme Dinge, die bis zum Frühling durchgetragen sein werden, und sie lernen, stolz darauf zu sein." } },
    revered = { title = "Ein junger Baum", { "Teldrassil ist sehr jung. Das vergessen die Leute, weil er sehr groß ist." }, { "Wir ließen ihn in Eile wachsen, in einer harten Zeit, und ein übereiltes Zuhause setzt sich langsam. Ein in Eile gemachtes Zuhause ist dennoch ein Zuhause, und ich liebe es. Aber ein junger Baum hat junge Sorgen, und eine junge Stadt hat mehr als ihren Anteil. Dinge gehen schief, die an einem Ort, der Jahrhunderte hatte, um sich zu setzen, nicht schiefgehen würden. Es liegt an uns, sie zu flicken." }, { "In windigen Nächten steige ich in die hohen Zweige und lausche dem Knarren des Baumes, und ich hoffe, dass er nur wächst." }, { "Jedes Stück, das an diesen Tisch gebracht wird, geht irgendwo in das Flicken. Eine Decke auf einem kranken Kind auf der Terrasse der Handwerker. Ein Verband für einen Druiden, der von einem Ast gefallen ist. Stoff auch für die Toten. Unsere Weber hatten nie zuvor ein Leichentuch gefertigt. Jetzt fertigen sie welche, und sie fertigen sie wunderschön, weil sie nicht wissen, wie man irgendetwas auf andere Weise macht." }, { "Manches davon war Eures. Ihr wusstet nicht, dass Ihr all das tatet. Ihr tatet es trotzdem.", after = 7792 } },
    aside = { title = "Geduld", { "Meine Weber haben angefangen, mit Namen nach Euch zu fragen. Sie sind kein gesprächiges Volk. Ich halte es für eine hohe Ehre, und ich hoffe, Ihr tut es auch." } },
    exalted = { title = "Der Saum", { "Unsere älteste Weberin hat angefangen, ihre Säume locker zu lassen." }, { "Sie webt schon länger, als irgendein Königreich der Menschen Aufzeichnungen führt, und all die Zeit fertigte sie Stoff, der ewig halten sollte. Feste Säume, verborgene Nähte, Fäden, die jeden überdauern würden, der sie trug. Das war die Kunst. Der Umhang eines Nachtelfen sollte sich nie abnutzen, weil der Nachtelf sich nie abnutzen sollte." }, { "Dann begann Euer Stoff über meinen Tisch zu kommen. Menschenwolle, Zwergenwolle, Gnomenseide, Stoff, gewebt von kurzlebigen Händen für kurzlebige Körper. Sie nahm ihn auseinander, um ihn zu verstehen, wie es eine Weberin tut. Und sie fand, dass die sterblichen Völker ihren Stoff locker säumen, damit man ihn auslassen kann, wenn ein Kind wächst, und flicken, wenn er reißt, und ausbessern, und weitergeben." }, { "So webt sie jetzt. Alle meine Weber tun es. Stoff, gefertigt im Wissen, dass er nicht halten wird, und gefertigt, um trotzdem geliebt zu werden." }, { "Ihr habt uns Stoff gegeben. In den Säumen habt Ihr uns, ohne es zu wollen, auch eine Art gegeben, ihn zu fertigen, die zu dem passt, was wir jetzt sind. Wir brauchten beides. Ich wusste nicht, wie ich Euch für das Zweite danken sollte, also habe ich sie gebeten, Euch einen Umhang auf die neue Art zu säumen. Er wird sich abnutzen. Darum geht es." } },
  },
  [54] = {
    start = { title = "In der Klemme", { "Ah! $gEin Kunde:Eine Kundin;! Na ja, $gein Spender:eine Spenderin;. Na ja, $gein möglicher Spender:eine mögliche Spenderin;, und das ist die allerbeste Sorte, denn Möglichkeiten sind etwas, das Gnome verstehen!" }, { "Wir Exilanten stecken in der Klemme, und da gibt es nichts schönzureden. Knapp an Stoff, knapp an Platz, knapp an allem außer Ideen, und um eine Idee kann man keinen Verband wickeln. Glaubt mir, ich habe es versucht. Heraus kam ein Bauplan." }, { "Bringt mir Stoff, irgendeinen Stoff, und die Gnome werden gut von Euch denken. Wir alle, überall. Das ist keine Kleinigkeit. Gnome sind überall, und wir haben ein langes Gedächtnis, und wir schreiben alles auf." } },
    friendly = { title = "Was wir zurückließen", { "Ihr wollt wissen, wofür all der Stoff ist, was?" }, { "Als wir aus Gnomeregan herauskamen, kamen wir in Eile heraus. Niemand hat gepackt. Man packt nicht, wenn die Stadt voller Troggs ist und die Luft schlecht geworden ist. Die Hälfte von uns ging in dem, was sie gerade trug, und eine ganze Menge von uns im Nachthemd, so erzählt man sich jedenfalls, und niemand denkt daran, eine schnellere Hose zu erfinden, bis er eine braucht." }, { "Also geht der Stoff zuerst in Kleidung. Dann in Decken, denn die Kälte hier oben hört nie auf. Dann in Verbände, denn die, die zurückgehen, um an den Toren zu kämpfen, kommen heim und brauchen welche. Dann, wenn noch etwas übrig ist, in Vorhänge. Ein Gnom mag Vorhänge. Sie lassen eine Ecke wie ein Zuhause wirken." }, { "Wir kommen voran. Ecke um Ecke." } },
    honored = { title = "Die Anschriften", { "Ich führe eine Liste. Lacht nicht. Na gut, lacht ein bisschen." }, { "Es ist jede Anschrift in Gnomeregan. Jede Straße, jede Ebene, jede Werkstatt und Wohnung und Kammer, und wem sie gehörte. Im ersten Winter schrieb ich sie aus dem Gedächtnis auf, und dann ging ich zu den Exilanten, einem nach dem anderen, und fragte sie, wo sie gewohnt hatten, und schrieb das auch auf. Manche weinten. Manche berichtigten mich. Einer berichtigte mich und weinte." }, { "Wer auch immer diese Straßen wieder betritt, wann immer das sein wird, muss nicht dastehen und sich fragen, welche Tür die seine war. Ich werde es aufgeschrieben haben. Er wird durch die richtige Tür gehen und finden, was übrig ist, und es wird das Seine sein." }, { "Darum geht es bei alldem eigentlich. Der Stoff hält uns bis dahin am Leben. Die Liste hält uns bei dem, was wir sind. Ich bewahre sie in einer Schachtel auf, die mit dem ersten Ballen ausgeschlagen ist, den mir hier je jemand gegeben hat." } },
    revered = { title = "Die Werkstatt", { "Meine Werkstatt lag auf einer unteren Ebene, hinter den großen Zahnrädern. Nichts Großartiges. Eine Werkbank, eine Lampe, ein Regal voller Teile, von denen ich sicher war, dass ich sie eines Tages brauchen würde, und die ich nie brauchte. Sie sind wahrscheinlich immer noch dort und sind im Dunkeln überflüssig." }, { "Als wir gingen, lag etwas auf der Werkbank. Halb fertig. Ich hatte ein Jahr daran gearbeitet, und es sollte das Beste werden, was ich je gebaut habe, und ich kann Euch nicht sagen, was es war. Nicht, weil es ein Geheimnis ist. Weil ich es vergessen habe. Ich habe es wieder und wieder versucht, und ich erinnere mich an die Werkbank und die Lampe, und das Ding darauf ist nur eine Form." }, { "Das ist der Teil, vor dem einen niemand warnt. Man denkt, man verliert die Stadt auf einen Schlag, am Tag, an dem man geht. Tut man nicht. Man verliert sie nach und nach, danach, im Kopf. Darum ist mir die Liste so wichtig, und darum vermerke ich darauf den Vorhang eines Gnoms so sorgfältig wie seine Tür." } },
    aside = { title = "Ecke um Ecke", { "Wisst Ihr, dass Ihr genug Stoff geschickt habt, um eine ganze Straße mit Vorhängen auszustatten? Ich habe eine Straße mit Eurem Namen angefangen. Nur die eine, fürs Erste." } },
    exalted = { title = "Das Banner", { "Kommt her. Vorsicht mit der Nadel." }, { "Das ist ein Banner. Oder es wird eines, wenn es fertig ist. Es ist für den Tag, an dem wir als Nächstes etwas zu feiern haben, denn an so einem Tag sollte jemand vorne etwas Weiches tragen, und ich habe beschlossen, dass ich das sein werde." }, { "Es ist aus Resten gemacht. Einer von allem, was an diesem Tisch gespendet wurde, seit dem ersten Winter. Wolle und Seide und Magiestoff und Runenstoff, alles zusammengenäht, und vieles davon kam von Euch. Der Flicken dort, und der da, und fast der ganze Rand. Ich hatte es nicht so geplant. Es ist einfach immer wieder passiert. Jeden Stich habe ich nachts gemacht, nachdem der Tisch geschlossen hatte, bei kleingedrehter Lampe. Es ist das Beste, was ich seit der Werkstatt gemacht habe, und dieses Mal werde ich es nicht vergessen." }, { "Ich habe keinen Witz dafür. Ich habe es versucht. Ich fange immer wieder einen an und höre dann auf, weil es nicht lustig ist, sondern einfach wahr. Ihr habt uns geholfen, lange genug am Leben zu bleiben, um etwas zu feiern zu haben. Wenn dieser Tag kommt, wird ein Teil von Euch vorne sein, im Wind." }, { "So. Das ist das Banner. Jetzt helft mir, den Faden einzufädeln, meine Hände sind nicht mehr, was sie waren." } },
  },
  [76] = {
    start = { title = "Für die Horde", { "Ihr da. Habt Ihr Stoff? Dann habt Ihr etwas, das die Horde braucht." }, { "Orgrimmar kämpft an jeder Front, die es gibt. Im Brachland, im Wald im Norden, in den Hügeln über dem Meer. Jeder Grunzer, der hinauszieht, muss vor dem Kampf eingewickelt und danach verbunden werden. Stahl kommt von den Schmieden. Stoff kommt von Leuten wie Euch, oder er kommt gar nicht." }, { "Gebt ihn her, und die Grunzer werden Euren Namen nicht kennen. Macht nichts. Sie werden wissen, dass sie es warm hatten und trocken und richtig verbunden waren, und das ist mehr, als die meisten Generäle ihnen je gegeben haben." } },
    friendly = { title = "Schatten", { "Kommt einen Moment in den Schatten." }, { "Durotar ist ein hartes Land. Die Sonne beißt, und der Sand dringt in alles. Niemand sonst wollte es. Mir recht. Wenn man lange genug gesagt bekommen hat, wo man zu leben hat, nimmt man einen Ort, den einem niemand wegnehmen kann." }, { "Jemandes Wolle wurde im Tal der Prüfungen als Sonnensegel aufgespannt. Ich ging hinunter, als sie es aufzogen. Die Jungen übten mit Äxten, stundenlang. Der Ausbilder rief eine Pause aus. Jeder Einzelne von ihnen ging zugleich unter Euer Sonnensegel, ließ sich fallen, wo er stand, und schlief auf einem Haufen, samt Äxten." }, { "Schatten ist kein Ruhm. War es nie. Ein Junger, der sich ausruhen darf, lernt schneller. Ein Grunzer, der aus der Sonne kommt, kämpft länger. Ich habe beide Sorten gekannt." }, { "Das war übrigens Eure Wolle.", after = 7826 } },
    honored = { title = "Die Lager", { "Ihr habt Euch eine Geschichte verdient. Es ist keine fröhliche." }, { "Nach dem Krieg, als die Menschen gewonnen hatten, steckten sie uns in Lager. Ganze Clans, hinter Mauern, mit Wachen auf den Mauern und nichts zu tun. Tag um Tag nichts. Ihr würdet staunen, was das Nichts mit einem Orc macht. Wir hörten auf, einander zu bekämpfen. Dann hörten wir auf zu reden. Dann hörten viele von uns auf, überhaupt etwas zu wollen. Wir trugen, was sie uns gaben. Sackleinen. Ihre abgelegten Sachen. Jahrelang, und nicht ein einziges Mal habe ich mir ausgesucht, was ich anzog." }, { "Dann kam der junge Kriegshäuptling und befreite uns, und wir kamen über das Meer in dieses Land. Das Erste, was ich tat, bevor ich einen Stein gelegt hatte, war, ein Stück Stoff einzutauschen und mir etwas zum Anziehen zu machen, das mir gehörte." }, { "Darum habe ich diesen Tisch übernommen. Jedes Stück, das darüber geht, ist eine Wahl, die uns die Lager nicht treffen ließen. Klingt nach viel, was man an etwas Wolle aufhängt. Ist es auch." } },
    revered = { title = "Die Jungen", { "Es gibt jetzt Orcs in dieser Stadt, die frei geboren sind. Sie haben nie ein Lager gesehen. Nie Sackleinen getragen. Sie wissen nicht, was eine Wache auf einer Mauer bedeutet, außer als eine von uns, die sie beschützt." }, { "Jeder von ihnen bekommt von mir einen ordentlichen Umhang, wenn er das Tal verlässt. Rot, wenn ich welchen habe. Sie nehmen ihn, ohne nachzudenken, so wie man etwas nimmt, das einem schon immer zustand. Dann rennen sie zu ihrem ersten Kampf und drehen sich nicht um." }, { "Das ist das Beste, was ich kenne. Ein junger Orc, der nicht weiß, wofür dieser Tisch da ist. Die Lager sind für sie eine Geschichte. Ich will, dass sie eine Geschichte bleiben." }, { "Ihr seid ein Teil davon. Was immer Ihr seid, wo immer Ihr geboren wurdet, Ihr habt Orcs Umhänge umgelegt, die Euren Namen nie kennen werden. Ein paar der Jungen kommen Jahre später an den Tisch zurück, mit ein oder zwei Narben und einem braun gewordenen Umhang, und bitten um einen neuen. Ich gebe ihn ihnen ohne ein Wort.", after = 7826 } },
    aside = { title = "Fronten", { "Ich lege jetzt einen roten Umhang in der Vorratskammer zurück. Niemand rührt ihn an. Fragt nicht, für wen er ist." } },
    exalted = { title = "Der Lumpen", { "Ich habe letzte Nacht den Lumpen zerschnitten." }, { "Den, den ich im Internierungslager trug. Was davon übrig war. Ich hatte ihn all die Jahre ganz unten in einer Truhe aufbewahrt. Dachte, wenn ich ihn loslasse, vergesse ich, und wenn ich vergesse, kann es wieder geschehen." }, { "Ich habe ihn nicht verbrannt. Ich habe den größten Teil der Nacht darüber nachgedacht. Verbrennen tut man mit einem Ding, vor dem man Angst hat, und ich habe keine Angst mehr davor. Also schnitt ich ihn in Streifen und nähte sie in den Saum des nächsten roten Umhangs, auf der Innenseite, wo niemand sie findet, außer er trennt ihn auf, und niemand trennt einen guten Umhang auf." }, { "Irgendeine junge Orcin wird die Lager in ihren Kniekehlen tragen und es nie wissen. Das ist der richtige Ort für sie. Darunter. Dahinter. Wie sie eine freie Orcin in ihren ersten Kampf trägt." }, { "Mit einer leeren Vorratskammer hätte ich es nicht gekonnt. Den letzten Fetzen von irgendetwas zerschneidet man nicht. Die Vorratskammer ist voll, weil Fremde sie voll gehalten haben, und ein guter Teil davon wart Ihr. Wenn genug da ist, kann man ein Ding loslassen." }, { "Sie bekommt den Umhang morgen. Sie wird ihn nehmen, ohne nachzudenken, und losrennen." } },
  },
  [81] = {
    start = { title = "Bruder, Schwester", { "Seid gegrüßt, $gBruder:Schwester;. Geht ein Stück mit mir, wenn der Wind es erlaubt." }, { "Mein Volk ist einen langen Weg gegangen, um auf diesen Klippen zu stehen, und der Weg war nicht leicht. Jetzt, da wir stehen geblieben sind, merken wir, dass wir Dinge brauchen, die wir unterwegs nie brauchten. Stoff ist eines davon. Er fehlt uns, bitter, und ich bin es, der darum bitten muss." }, { "Ich bitte nicht leicht. Verzeiht mir, wenn ich langsam darin bin. Wenn Ihr Stoff entbehren könnt, würden die Tauren ihn dankbar annehmen. Eine Freundlichkeit gegenüber einem von uns schulden wir alle, solange die Klippen stehen." } },
    friendly = { title = "Felle", { "Jede Gabe an diesem Tisch zählt mehr, als Ihr vielleicht denkt." }, { "Solange die ältesten Lieder zurückreichen, folgten wir den Herden. Wir trugen Felle und schliefen unter Fellen und trugen unser Leben auf dem Rücken und auf den Kodos. Fell ist gut für die Straße. Es ist stark, und es ist unseres. Aber Fell webt man nicht, und ein Fieber wickelt man nicht darin ein, und ein Kind wächst in einer Jahreszeit aus einem Fellmantel heraus, wenn ein Fell eine Jahreszeit zum Gerben braucht." }, { "Jetzt leben wir an einem Ort, und die Bedürfnisse eines Ortes sind uns neu. Decken, die man waschen kann. Verbände für die Verwundeten, die aus dem Brachland zurückkommen. Stoff für die Hütten, damit der Wind nicht jeden Spalt findet." }, { "Wir lernen. Euer Stoff hilft uns, schneller zu lernen, als der Stolz es uns erlauben würde." } },
    honored = { title = "Bleiben", { "Meine Großmutter hielt ihr Bündel an der Tür der Hütte bereit, bis zu dem Tag, an dem sie starb." }, { "Sie kam mit uns allen auf die Klippen, und sie willigte ein zu bleiben, und sie meinte es so. Aber jeden Abend, bevor sie schlief, sah sie nach dem Bündel. Jeden Morgen stand sie am Rand der Anhöhe und blickte zum Horizont, als könnten die Herden sie rufen und sie müsste bereit sein." }, { "Wir baten sie nie, es auszupacken. Das verlangt man nicht von jemandem, der dieses Land öfter von einem Ende zum anderen durchwandert hat, als sie zählen konnte. Als sie starb, stand das Bündel immer noch an der Tür, immer noch bereit. Meine Mutter leerte es. Sie brauchte einen ganzen Tag dafür, weil sie immer wieder innehielt." }, { "Das Bleiben kostete meine Großmutter jeden Morgen etwas. Es kostet uns alle ein wenig. Wenn ich Euren Stoff an die Hütten weitergebe, denke ich an dieses Bündel, und ich bin froh über jedes warme Ding, das das Bleiben leichter macht." } },
    revered = { title = "Die Gaben der Erdmutter", { "Wir glauben, dass alles von der Erdmutter kommt. Das Gras, das die Herden fressen, die Herden selbst, die Felle, die wir trugen, der Flachs, den wir anzubauen lernen. Immer eine Gabe. Frei gegeben, und mit Fürsorge vergolten." }, { "Wenn ich also von jemandem Stoff nehme, nehme ich ihn als eine Gabe, die aus ihren Händen durch die seinen ging. Das Schaf, dem die Wolle wuchs, die Spinne, die die Seide spann, die Hände, die sie webten, und die Hände, die sie hierhertrugen. Das sind sehr viele Hände. Ich versuche, jede von ihnen zu ehren." }, { "Ich glaube inzwischen, dass dieser Tisch ein kleines Gebet ist. Ein kleines. Die Schamanen sprechen die großen, und sie sprechen sie besser. Das tun sie meistens. Dies ist nur ein Tauren, der an einem Ort steht, nimmt, was gegeben wird, und es an die weitergibt, die es brauchen, so wie es das Land tut. Wenn die Schamanen beten, hört der Himmel zu. Wenn ich bete, bekommt ein Kind eine Decke. Ich würde nicht tauschen." }, { "Ihr wart ein großer Teil dieses Gebets, ob Ihr beten wolltet oder nicht.", after = 7820 } },
    aside = { title = "Der Anteil des Windes", { "Wenn der Wind oben auf den Anhöhen stark weht, knarren die Hütten, und die Alten sagen, er verlange mehr von Eurem Stoff. Ich habe dem Wind gesagt, er soll warten, bis er an der Reihe ist." } },
    exalted = { title = "Bitten", { "Mein Großvater hätte niemanden um etwas gebeten." }, { "Er war ein großer Jäger und ein stolzer, und er glaubte, ein Tauren, der Hilfe braucht, habe irgendwo versagt. Er starb unterwegs, so wie er es wollte, und er hat in seinem ganzen Leben keinem Fremden die Hand hingehalten. Er gab mir diesen Namen, Proudstrider, der stolz Schreitende. Ich liebte ihn. Ich war stolz auf ihn." }, { "Ich glaube, er hatte Unrecht." }, { "Ich bitte nun seit Jahren jeden Tag Fremde um Stoff. Zuerst beschämte es mich. Ich bat leise, und schlecht, und murmelte meinen Dank in meine Brust. Dann gaben die Gebenden immer weiter, großzügig, ohne etwas zurückzuwollen, und irgendwo auf dem Weg wich die Scham. Das Bitten wurde zu einer Art Vertrauen. Man vertraut dem, den man bittet, und er vertraut einem, die Gabe gut zu verwenden." }, { "Ich habe eine Tochter. Sie ist noch klein und schon stolz, wie er. Also bitte ich Euch zum ersten Mal um etwas, das kein Stoff ist. Wenn sie eines Tages erwachsen ist und einen Fremden um Hilfe bitten muss und nicht weiß, wie, seid einer der Fremden, die sie bittet. Antwortet ihr so, wie Ihr mir geantwortet habt." } },
  },
  [68] = {
    start = { title = "In Eurem eigenen Interesse", { "Ihr da. Hört genau zu. Ich sage Dinge ungern zweimal." }, { "Die Verlassenen brauchen Stoff. Wolle, Seide, was Ihr gerade bei Euch tragt. Lasst ihn bei den Schreibern. Sie werden ihn wiegen und in ein Hauptbuch eintragen, das niemand liest außer mir, und ich lese es jede Nacht, Zeile für Zeile." }, { "Nichts, was an diesem Tisch zurückgelassen wird, bleibt unverzeichnet. Nichts, was hier gegeben wird, bleibt unbemerkt. Die meisten finden das beruhigend. Manche finden es bedrohlich. Beides ist richtig, und ich überlasse es Euch zu entscheiden, was Ihr seid." } },
    friendly = { title = "Warum die Toten Verbände brauchen", { "Es kommt weiter Stoff an diesen Tisch. Nun gut. Ihr solltet wissen, wozu er dient." }, { "Die Lebenden heilen. Sie schneiden sich, und nach einer Woche ist da eine Narbe, und sie vergessen es. Wir heilen langsam und schlecht und nie ganz. Die Apotheker können nähen und salben und die Fäulnis verlangsamen, aber was der Körper verliert, gibt er nur langsam zurück. Also verbinden wir es. Wir wickeln, was lose ist, und halten, was offen ist, und halten uns mit Stoff zusammen, so wie Ihr einen gesprungenen Krug mit Schnur zusammenhalten würdet." }, { "Ein Soldat der Verlassenen verbraucht Verbände schneller als jeder Lebende, und er braucht sie, um sich selbst zusammenzuhalten." }, { "Die Schreiber finden die Frage, warum die Toten so viel Leinen brauchen, ermüdend. Ich auch. Stellt sie noch einmal, und ich lasse Euch im Hauptbuch unter Plagegeister eintragen." } },
    honored = { title = "Der Händler", { "Früher verkaufte ich Seide." }, { "In Lordaeron. Der Stadt über uns, als sie noch eine Stadt war. Ich hatte einen Laden abseits des Platzes, und der Hof kaufte bei mir, und ich kannte das Gewicht jedes Ballens, den ich verkaufte, und den Namen jeder Dame, die ihn trug. Ich war gut darin. Ich war stolz darauf, gut darin zu sein. Das, sagt man mir, ist etwas sehr Lebendiges." }, { "Dann kam die Seuche, und dann der Rest. Ich kam in den Ruinen oben wieder zu mir, mit denselben Händen und keinem einzigen derselben Kunden, und später kam ich hier herunter. Das Erste, was man mir zu tun gab, war, Verbände zu zählen. Die gröbste Wolle, um tote Soldaten zusammenzuhalten." }, { "Ich hätte mich weigern können. Ich kannte einige, die es taten, in jenen ersten Jahren. Ich tat es nicht. Es stellte sich heraus, dass ein Händler, der sich mit Stoff auskennt, auch den Toten nützlich ist. Die Ironie ist lehrreich." } },
    revered = { title = "Die Lebenden", { "Das meiste, was über diesen Tisch geht, kommt von den Toten. Wir sorgen für die Unseren. Aber manches kommt von den Lebenden. Orcs, Trolle, Tauren." }, { "Sie tragen etwas mit herein, das sie nicht bemerken. Wärme, wahrhaftig, von ihren Händen und ihrem Atem, und noch eine kleine Weile auf dem Stoff, nachdem sie ihn abgelegt haben. Ich kann sie spüren, wenn ich schnell bin. Sie verfliegt in ein, zwei Minuten. Hände der Verlassenen tragen nichts dergleichen. Ich habe meine eigenen geprüft. Trolle sind kühl, Orcs heiß, und die Tauren am wärmsten von allen." }, { "Früher war ich warm. Ich erinnere mich daran, wie man sich vielleicht an eine Sprache erinnert, die man als Kind gesprochen hat. Ich könnte kein Gespräch mehr in ihr führen. Aber ich erkenne sie, wenn ich sie höre." }, { "Euer Stoff ist der einzige, den ich zweimal prüfe, was immer er trägt. Ich erzähle den anderen Schreibern nicht, dass ich warte, nachdem Ihr gegangen seid, bevor ich ihn weglege.", after = 7813 } },
    aside = { title = "Bestandsaufnahme", { "Ich habe die Schreiber angewiesen, Euren Stoff nicht mehr zu wiegen. Sie bestätigten nur, was ich ohnehin wusste." } },
    exalted = { title = "Worin die Apotheker irren", { "Als Ihr das erste Mal kamt, sagte ich, dass nichts, was hier gegeben wird, unbemerkt bleibt. Ich meinte es ebenso als Drohung wie als Versprechen. Heute ist es nur noch ein Versprechen." }, { "Die Apotheker werden Euch sagen, dass die Toten nichts fühlen. Sie haben es untersucht. Sie haben Abhandlungen. Sie werden Euch sagen, dass das, was wir Gefühl nennen, eine Gewohnheit des Körpers ist, ein Zucken, das vom Leben übrig ist, und dass es verblasst, und dass ein vernünftiger Verlassener es verblassen lässt." }, { "Die Apotheker irren sich in sehr vielen Dingen. In diesem irren sie sich." }, { "Ich habe an diesem Tisch etwas gefühlt, lange bevor es einen Namen hatte. Etwas, das der Dankbarkeit nahekam, die ich zu den Dingen gezählt hatte, die ich auf dem Weg hier herunter verlor. Sie war nicht verloren. Sie wartete auf einen Grund, und der Grund kam immer wieder mit vollen Armen." }, { "Ich habe aufgehört, den Apothekern zu sagen, dass es das nicht gibt. Sie haben mich vermutlich in ihr eigenes Hauptbuch eingetragen, unter Kuriositäten. Damit kann ich leben, in dem Sinne des Wortes, der auf mich zutrifft. Irgendjemand muss in ihrem Hauptbuch die Ausnahme sein. Es kann ebenso gut jemand sein, der gute Bücher führt." } },
  },
  [530] = {
    start = { title = "Das Gewebe", { "Kommt, kommt. Bringt das her, lasst Vehena mal fühlen." }, { "In jedem Stück Stoff steckt eine Geschichte, wisst Ihr. Wo das Schaf geweidet hat, was die Spinne gefressen hat, wer ihn getragen hat und wie weit. Die meisten Leute können sie nicht hören. Vehena schon. Ein Geschenk der Loa, sagte meine Großmutter, oder ein Fluch, je nach Stoff." }, { "Die Dunkelspeere brauchen Stoff. Verbände, Wickel, Segel, Decken für die Kleinen unten in Sen'jin an der Küste. Bringt mir welchen, und ich sage Euch, wo Ihr gewesen seid. Kostenlos. Die Loa mögen es nicht, wenn ich etwas verlange." } },
    friendly = { title = "Wo Ihr gewesen seid", { "Ah, nun. Lasst mich Euch lesen. Kein Stoff in Euren Händen? Dann lese ich die Hände. Die waren auf einer langen Straße. Da ist Staub drauf von einem heißen Ort, und etwas Kälteres darunter, von davor. Gekämpft habt Ihr auch. Die Hände erinnern sich." }, { "Vehena weiß Dinge." }, { "Ein Fischer unten im Dorf hat letzten Monat sein Segel in einer Bö verloren. Die erste Wolle, die danach durch meine Hände ging, ging die Straße hinunter zu ihm, und seine Tochter hat sie angenäht, und jetzt fährt jeden Morgen ein Boot unter dem Geschenk eines Fremden hinaus. Wir Dunkelspeere sind jetzt ein Seevolk. Ein Boot ohne Segel ist ein Troll ohne Abendessen." }, { "Das war übrigens Eure Wolle. Das Boot fährt unter einem Segel hinaus, das ganz leicht nach Euch riecht. Das Dorf dankt Euch. Die Loa, die sind immer dankbar, aber bei den Loa kostet es immer etwas.", after = 7833 } },
    honored = { title = "Die Inseln", { "Vor der Küste, hinter Sen'jin, liegen die Echoinseln. Die sollten in diesem Land unsere Heimat sein." }, { "Ein Hexendoktor da draußen hat sich dem Bösen verschrieben. Zalazane. Er hat die Inseln für sich genommen, und Trolle mit ihnen, unsere eigenen, so tief verhext, dass sie ihre Namen nicht kennen. Sie gehen mit leeren Gesichtern an seinen Stränden und tun, was er sagt." }, { "Ab und zu kommt einer von ihnen zu uns zurück. Wie, könnte ich Euch nicht sagen. Meine Großmutter sagte, der Fluch wird dünn mit der Entfernung, wie ein Seil. Sie kommen mit nichts ins Dorf. Nicht einmal mit ihrem eigenen Verstand, zuerst. Wir wickeln sie ein. Wir bringen sie ans Feuer. Wir sagen ihnen ihre Namen, bis sie sie zurücksagen." }, { "Ein guter Teil dessen, was an diesen Tisch kommt, geht dorthin. Decken für Trolle, die nicht wussten, dass ihnen kalt war. Aus diesem hier lese ich nichts. Ich sage Euch einfach danke, und dabei bleibt es." } },
    revered = { title = "Die Loa", { "Die Loa bemerken alles, wisst Ihr. Jede Gabe. Jeden Diebstahl." }, { "So wie meine Großmutter es lehrte, feilscht man mit ihnen. Ein wenig Rauch, ein wenig von dem, was man am meisten liebt, und die Loa geben zurück, was ihnen gefällt. Die Dunkelspeere haben die alten Loa mit über das Meer gebracht, und sie sind gekommen, und sie sind hier, im Rauch der Dorffeuer." }, { "Die Gaben an diesem Tisch bemerken sie. Vehena weiß es, weil die Feuer leichter brennen in den Nächten, nachdem Stoff gekommen ist. Vielleicht sind das die Loa. Vielleicht sind das nur mehr Decken, damit mehr Trolle warm schlafen und niemand aufbleiben muss, um das Feuer zu füttern. Beides ist wahr, glaube ich. Die Loa mögen es, wenn beides wahr ist." }, { "Ich habe selbst einen Handel gemacht, als ich jung war. Ein wenig von dem, was ich am meisten liebte, für ein wenig Glück. Ich gab ihnen meine Singstimme. Habe sie nie zurückbekommen. Auf das Glück warte ich noch. Vielleicht kam es in jemandes Wolle eingewickelt, und ich hab es nicht bemerkt." } },
    aside = { title = "Eine lange Straße", { "So viel Straße steckt jetzt in Eurem Stoff, Vehena könnte die Welt danach zeichnen. Keine Sorge. Die peinlichen Stellen lasse ich weg." } },
    exalted = { title = "Der Trick", { "Ich kann keinen Stoff lesen." }, { "Konnte ich nie. Keinen Faden. Kein Loa hat mir je diese Gabe gegeben, und ich habe gefragt. Es ist ein Trick. Man hält den Stoff, man fühlt das Gewicht, man riecht daran, man mustert den Fremden, der ihn hinhält, und man sagt etwas von einer langen Straße und einem kalten Ort und Kämpfen. Jeder war auf einer langen Straße. Jedem war kalt. Jeder hat gekämpft. Sie nicken, und sie staunen, und dann reden sie, und das wollte ich. Leute, die reden, geben mehr." }, { "Ich mache das schon so lange, dass ich es halb selbst glaube. In manchen Nächten glaube ich es ganz." }, { "Aber irgendwann, mit Euch, habe ich aufgehört. Ich weiß nicht, wann. Ich merkte nur eines Tages, dass ich ganz schlicht redete und das Gerede weg war, und ich habe es nicht vermisst." }, { "Also mache ich es von jetzt an so. Den Trick behalte ich für das Dorf. Sie mögen ihn, und er tut ihnen gut, und es ist nichts Schlimmes daran. Wer mich geradeheraus fragt, dem antworte ich geradeheraus. Und wenn der nächste Fremde mit einem Armvoll Wolle und diesem Blick im Gesicht ankommt, denke ich an Euch, und vielleicht sage ich einfach danke und lasse das Lesen weg." } },
  },
  [21] = {
    start = { title = "Stille Gäste", { "Booty Bay, $gPartner:Partnerin;. Hier ist jeder ein Partner, bis das Gegenteil bewiesen ist." }, { "Trinkt etwas. Gebt Geld aus. Ich verlange eine Sache von einem Gast, und zwar, dass nichts geschieht, während er hier ist. Gar nichts. Meine Rausschmeißer sind sehr gut darin, dafür zu sorgen, und sie bekommen ein wenig extra, wenn sie es müssen." }, { "Ihr seid noch niemand für mich, und das meine ich freundlich. Die meisten Leute in dieser Bucht sind niemand für mich. Die, die zählen, sind die, die etwas für das Steamwheedle-Kartell tun, und für den Goblin, der seinen Hafen führt. Tut etwas, und wir reden wieder." } },
    friendly = { title = "Wofür die Bucht da ist", { "Nun denn. Mir kam zu Ohren, dass Ihr Dinge für das Kartell getan habt. Jetzt dürft Ihr wissen, wofür diese Bucht da ist." }, { "Booty Bay hat eine eigene Flotte, und die Flotte ist meine. Die Schwarzmeerräuber segeln aus diesem Hafen, und mein Flottenmeister hält die Seewege für jeden offen, der das Kartell bezahlt. Draußen hinter der Landspitze hätte eine Flotte unter roten Segeln diese Seewege gern für sich, und das nehme ich persönlich. Das sollte jeder, der meinen Schnaps trinkt." }, { "Im Landesinneren plündert die Venture Company den Dschungel um Holz und Erz. Das sind auch Goblins, und das hat noch nie entschieden, auf wessen Seite ein Goblin steht. Ich habe nie viel für einen Goblin übriggehabt, der dort gräbt, wo ich ihn hören kann." }, { "Tut weiter Dinge, und die Bucht wird anfangen, Platz für Euch zu machen." } },
    honored = { title = "Die Sammlung", { "Kommt herein. Fasst nichts an." }, { "Ich sammle. Trolldinge, meistens, aus dem Reich, das diesen Dschungel hielt, lange bevor irgendwer daran dachte, hier einen Hafen anzulegen. Masken, Götzenbilder, Klingen, die niemand heben kann. Die Gurubashi fertigten schöne Dinge aus schrecklichen Gründen, und die Gründe haben mich nie gestört." }, { "Es gab ein Stück, das ich mehr wollte als alle anderen. Den Stein der Gezeiten. Ich las zuerst in einem alten Buch mit Trolllegenden davon: ein Stein, der eine Flut in sich hält, und ein Fluch auf dem, der ihn trägt, der aus der Welt verblasst und wieder zurück. Ein Goblinzauberer namens Gazban soll ihn gefunden haben. Gazban stellte sich als Geist heraus. So viel dazu, dass der Fluch eine Geschichte sei." }, { "Er steht jetzt auf seinem eigenen Sockel, und die Flut in ihm hört nie auf, sich zu bewegen. Ihr habt ihn mir gebracht, und Gazban ist endlich still. Niemand sonst hat ihn seitdem berührt, und niemand wird es.", after = 611 } },
    revered = { title = "Ohren", { "Krazek lauscht für mich. Er hält sich in der Taverne auf und hört jedes Gerücht, das an Land kommt, die seltsamen besonders, und bringt sie die Treppe herauf. Andere ebenso, deren Namen Ihr nie erfahren werdet. Krazek hat ein gutes Ohr und ein schlechtes Gedächtnis für Gesichter. Für seine Arbeit ist das genau richtig herum. Das meiste, was in meiner Bucht gesagt wird, erreicht mich, bevor die, die es sagen, ihr Glas geleert haben." }, { "So bleibt ein Baron ein Baron. Wer sich mit mir anlegt, kommt nicht dazu, hinterher darüber zu reden, weil ich zuerst davon höre. Einsam, stellen sich Besucher vor. Meistens ist es eine Frage des Wissens, was die Treppe heraufkommt." }, { "Euer Name ist diese Treppe oft heraufgekommen, aus dieser Bucht und aus den anderen Städten des Kartells, die mir mehr erzählen, als sie zugeben. Ich habe mir alles angehört. Ich habe Leute für weniger beobachten lassen, und für weniger belohnt, und ich war mir nie unsicher, was ein Mann verdiente. Bei Euch war ich es eine Weile." } },
    exalted = { title = "Die Treppe", { "Krazek kam heute Morgen mit Eurem Namen die Treppe herauf, und ich schickte ihn wieder hinunter. Er nahm es schwer. Zuhören ist das Einzige, wofür er je gelobt wurde." }, { "Ich sagte ihm, ich würde es bei Euch nicht mehr brauchen. Von all den Leuten, die in dieser Bucht kommen und gehen, seid Ihr $gderjenige, auf den:diejenige, auf die; ich aufgehört habe zu lauschen. Es hat lange gedauert, bis ich das geschafft habe, und ich bin mir immer noch nicht sicher, ob mir gefällt, wie es sich anfühlt." }, { "An jenem ersten Tag verlangte ich eine Sache von Euch, dass nichts geschehe, während Ihr hier seid. Ich nehme es zurück. Ihr wart $gder ereignisreichste Gast:die ereignisreichste Besucherin;, den diese Bucht seit Jahren hatte, und jedes Ereignis lief zu meinen Gunsten. Macht so viel Ärger, wie Ihr wollt." }, { "Die roten Segel sind immer noch draußen hinter der Landspitze, die Venture Company gräbt immer noch, wo ich sie hören kann, und es wird immer jemanden auf der Treppe geben, der meint, das oberste Stockwerk stünde ihm besser. Das ist die Bucht, und ich würde sie nicht ändern. Sie lässt sich ein wenig leichter führen, mit einer einzigen Person darin, der ich vertraue, ohne nachzuprüfen." } },
  },
  [369] = {
    start = { title = "Der Preis des Wassers", { "Ihr da! Durstig? Natürlich seid Ihr das. Das hier ist Tanaris." }, { "Chefingenieur, Wasserkompanie von Gadgetzan. Ich halte die Brunnen am Pumpen, die Pumpen am Laufen und den Preis fair. Fair für die Kompanie, meine ich. Jedes einzelne Ding in Gadgetzan kostet etwas, Wasser am meisten, und wenn Ihr wegen Mitgefühl statt wegen Wasser gekommen seid, draußen vor dem Tor gibt es eine ganze Wüste davon." }, { "Die Nomaden da draußen werden Euch sagen, Wasser sollte umsonst sein. Die Nomaden haben auch unsere Brunnen genommen und die Leute getötet, die sie betrieben." } },
    friendly = { title = "Gerechtigkeit", { "Jetzt seid Ihr jemand, mit dem die Kompanie reden kann!" }, { "Die Lage ist folgende. Die Nomaden der Wüstenläufer haben fast jeden Brunnen in dieser Wüste genommen. Unsere Brunnen. Wir haben sie gegraben, wir haben sie angetrieben, wir haben unsere Leute hinausgeschickt, um sie am Laufen zu halten, und die Nomaden haben diese Leute getötet und das Wasser behalten. Manche würden das einen Geschäftsstreit nennen. Die Kompanie nennt es Diebstahl mit Leichen." }, { "Ihr Anführer heißt Kalif Skorpidstich. Die Kompanie hat sein Gesicht auf ein Plakat zeichnen und einen Preis darunter schreiben lassen, und der Preis ist ein guter." }, { "Was immer Ihr für die Kompanie getan habt, die Kompanie hat es bemerkt, und sie vergisst nicht, wer geholfen hat. Eines Tages kommen diese Brunnen zu uns zurück. Ich gedenke, mit einem Schraubenschlüssel am ersten zu stehen." } },
    honored = { title = "Die Rute", { "Wollt Ihr wissen, wie ein Goblin in einem Meer aus Sand Wasser findet? Ingenieurskunst! Und ein Stock." }, { "Die Wünschel-mato-Rute. Man geht damit über die Dünen, und wenn tief darunter Wasser ist, weiß sie es, und man gräbt, und die Kompanie hat einen neuen Brunnen. Jedes neue Loch, das ich gegraben habe, begann mit dieser Rute in meinen Händen. Eher würde ich eine Hand verlieren." }, { "Dann bat Sergeant Bly darum, sie sich zu borgen. Borgen! Er nahm sie mit auf Schatzsuche bei den Trollen von Zul'Farrak, mit einer Bande von Abenteurern der übelsten Sorte, und er brachte sie nie zurück. Wer einem Goblin sein Gold stiehlt, ist ein Dieb. Wer einem Goblin in einer Dürre seine Wünschelrute stiehlt, ist etwas, das ich vor Kunden nicht sagen darf." }, { "Seit sie wieder zu Hause ist, findet sie wieder Wasser. Die Kompanie hat aufgehört, mich zu fragen, woher die neuen Löcher kommen, und ich habe aufgehört, es zu erklären.", after = 2768 } },
    revered = { title = "Schnee", { "Die Kompanie hat einen langen Plan, und ich bin der Einzige, der ihn gezeichnet hat." }, { "Dun Morogh! Oben im Norden haben die Zwerge Quellen, so kalt, dass einem das Wasser in den Zähnen wehtut. Mehr Wasser, als sie wissen, wohin damit. Eis fällt bei ihnen vom Himmel, umsonst, den ganzen Winter lang! Eines Tages leiten wir es her, oder verschiffen es, oder schneiden es in Blöcke und schleppen es über das Meer, und Gadgetzan ist nie wieder durstig. Niemand streitet sich um einen Eimer. Niemand wird an einem Brunnen getötet. Ich kann aufhören, Energiequellen an Leute zu verkaufen, die sie in den Sand fallen lassen." }, { "Bis dahin verkaufe ich Wasser und Energie und Geduld, und ich verlange für alle drei etwas. Das Geld geht irgendwohin, darum geht es. Ich habe eine Schublade voller Zeichnungen dafür, und eine Zeichnung von einem Baum, auf dem Energiequellen wachsen. Die Kompanie hat mich gebeten, die nicht mehr in Besprechungen mitzubringen." }, { "Ich würde gern lange genug leben, um mich beim Wasser zu langweilen. Stellt Euch das vor. Ein Goblin in Tanaris, gelangweilt vom Wasser." } },
    exalted = { title = "Aufs Haus", { "Haltet Eure Hände auf." }, { "Das ist ein Becher Wasser. Kalt und sauber, aus dem tiefen Brunnen, dem guten. Er ist umsonst. Ich habe geübt, das zu sagen. Es klingt immer noch seltsam." }, { "Macht nicht so ein Gesicht. Ich weiß, was ich am ersten Tag gesagt habe, und ich meinte es, und ich meine es für alle anderen immer noch. In Gadgetzan kostet alles etwas. Aber die Kompanie schuldet Euch etwas, und die Kompanie zahlt, was sie schuldet, und heute bin ich die Kompanie, und ich sage, dieser hier geht aufs Haus." }, { "Was immer Ihr für diese Stadt getan habt, Ihr habt es für einen Ort getan, der Euch für jeden Schluck etwas berechnet hat, und Ihr habt weitergemacht. Ihr habt mich ertragen. Meine eigenen Ingenieure würden Euch sagen, dass das der schwere Teil ist." }, { "Und dann ist da der Kalif. Die Kompanie hat das Kopfgeld für ihn gezahlt, und ich habe nichts dazugelegt, denn das Geld der Kompanie gehört der Kompanie. Dieser Becher ist meiner.", after = 2781 }, { "Trinkt langsam. Es schmeckt besser, wenn niemand etwas dafür verlangt. Wenn sich herumspricht, dass der Chefingenieur Wasser verschenkt hat, steht bis Mittag eine Schlange um den Block, und ich werde alles abstreiten." } },
  },
  [470] = {
    start = { title = "Die Docks", { "Gazlowe. Ich führe Ratchet. Schiffe kommen rein, Schiffe gehen raus, Waren wechseln den Besitzer, ich nehme mir ein bisschen was oben ab, und alle gehen glücklich nach Hause. So die Theorie." }, { "Die Praxis sind Piraten. Die Südmeerfreibeuter überfallen meine Schiffe an der ganzen Küste rauf und runter, und neuerdings haben sie ihre Zelte einen kurzen Spaziergang von meinen Docks entfernt aufgeschlagen. Die Handelsprinzen haben ein Vermögen in die Flotten versenkt, die sie aufhalten sollen, und mir fehlen immer noch eine Linse, eine Kiste Stiefel und eine ruhige Nacht." } },
    friendly = { title = "Die Lohnliste", { "$gKleiner:Kleine;! Ihr taucht in meinen Büchern langsam auf der richtigen Seite auf." }, { "Ratchet funktioniert so. Jeder, der zählt, steht auf der Lohnliste. Der Werftmeister, die Schläger, der Kerl, der nach den Schlägern sieht. Dizzywig führt die Docklisten, und ich traue seinen Listen, weil ich ihn bezahle." }, { "Dann gibt es die Leute, die man nicht bezahlen kann. Piraten, meistens. Und den Vizeadmiral, dessen ganze Aufgabe es ist, diese Gewässer frei zu halten, und der nicht mal eine Badewanne frei halten könnte. Jedes Mal, wenn ein Freibeuter mit meiner Fracht an Bord an Grezzliks Flotte vorbeisegelt, schreibe ich es auf. Ich habe ein ganzes Buch voll Grezzlik." }, { "Was immer Ihr für das Kartell getan habt, für mein Geld habt Ihr es nicht getan. Dafür zahle ich zu schlecht. Ich finde immer noch heraus, wofür Ihr es tut." } },
    honored = { title = "Die Gnadenlos", { "Die Gnadenlos ist vor Jahren einmal auf See an mir vorbeigefahren. Was für ein Rumpf. Lang und flach und schnell, gebaut, das würde ich schwören, von jemandem, der Boote mehr liebte als Geld. Ich kenne die Krankheit. Irgendwo habe ich noch eine Skizze ihrer Linien." }, { "Ihr Kapitän war Baron Küstenschipper, aus Gilneas, und er benutzte dieses schöne Schiff, um für die Südmeerfreibeuter meinen Schiffen zuzusetzen. Ich ließ seinen Namen auf einen Steckbrief setzen und meinte jedes Wort. Ich hoffte auch ein bisschen, dass, wer immer ihn erledigte, das Schiff ganz lassen würde. Man kann einen Mann fortwünschen und trotzdem sein Boot wollen." }, { "So läuft das mit Piraten. Sie bestehlen einen mit der Arbeit der besten Schiffbauer auf See, und man hasst sie dafür, und man macht sich Notizen." }, { "Er wird jetzt niemandem mehr zusetzen. Das Kopfgeld habe ich gern bezahlt. Ich habe nie gefragt, was aus der Gnadenlos wurde. Für manche Dinge will ein Goblin keine Rechnung.", after = 895 } },
    revered = { title = "Kein Geld drin", { "Das da oben auf dem Hügel ist meine Sternwarte. Fragt nicht, was sie einbringt." }, { "Eine Karawane brachte mir die erste Linse aus Durotar. Ein Schiff sollte mir die zweite bringen, und die Piraten erwischten das Schiff. Fast hätte ich die ganze Sache aufgegeben." }, { "Dann seid Ihr in ihr Lager gegangen und mit der Linse wieder herausgekommen, und jetzt kommt in einer klaren Nacht der Himmel bis nach Ratchet herunter.", after = 888 }, { "Die Leute fragen, was ein Goblin mit den Sternen will. Es ist kein Geld drin. Das ist der ganze Reiz." }, { "Genauso mit Pozziks Rennteam. Ich finde in jedem Hafen, den ich habe, Teile für sie, und einmal habe ich mir die eigenen Hände schwarz gemacht, als ich an einem der Gefährte mitgearbeitet habe, und so glücklich war ich seitdem auf keinem Dock mehr. Kein Gewinn darin. Keiner. Die Gnome holen immer noch auf, und ich schicke immer weiter Teile." }, { "Alles andere, was mir gehört, bringt Geld. Diese beiden Dinge sorgen nur dafür, dass ich morgens gern aufstehe. Lorenhall würde davon auch einen Anteil wollen." } },
    exalted = { title = "Was ich gebaut habe", { "Ich habe in meinem Leben eine Menge Dinge gebaut, $gKleiner:Kleine;." }, { "Eine Stadt, einmal, für einen Kriegshäuptling der Orcs, der pünktlich zahlte. Ihr würdet staunen, wie selten das vorkommt. Diesen Hafen, Planke für Planke. Eine Sternwarte, um die keiner gebeten hat. Treibstoffleitungen für Rennfahrer, die vielleicht nie gewinnen. Ich kann Euch sagen, was in jedes davon geflossen ist, bis zum letzten Nagel." }, { "Das Problem ist folgendes. Ich habe das Geld für ein weiteres, und zwei Zeichnungen auf dem Tisch. Ein Wellenbrecher draußen hinter den Docks, damit die Südmeerfreibeuter nicht bis an meine Lagerhäuser segeln. Oder ein ordentlicher Leuchtturm auf der Landspitze, damit nie mehr jemand Ehrliches bei der nächtlichen Einfahrt auf Grund läuft. Der Wellenbrecher ist vernünftig. Der Leuchtturm ist schön. Ich bin seit einem Monat hin und her gegangen und habe jedes Mal verloren." }, { "Also frage ich Euch. Ihr habt mehr für dieses Kartell getan als die meisten Goblins, die hineingeboren wurden, und Ihr habt so oder so kein Geld darauf gesetzt. Sucht eines aus. Ich baue es, und wenn mich jemand fragt, warum gerade das, sage ich ihm, wessen Idee es war." }, { "Lasst Euch Zeit. Nicht zu viel. Holz wird nicht billiger." } },
  },
  [577] = {
    start = { title = "Neu in der Stadt", { "Oh! Hallo! Ihr seid neu. In Everlook ist jeder ungefähr einen Tag lang neu, und danach ist ihm nur noch kalt, wie uns anderen." }, { "Ich bin Umi. Ich wohne hier. Eine Gnomin in einem Handelsposten der Goblins, dort oben, wo sich alle Straßen von Winterspring kreuzen, und draußen vor den Mauern nichts als Schnee und Dinge, die einen fressen wollen. Mir gefällt es. Hier werden Dinge gebaut und gehandelt und beredet." }, { "Meine Freunde sind klug. Jeder von ihnen hat immer irgendeinen wunderbaren Plan am Laufen, und sie lassen es mich nie vergessen. Eines Tages werde ich einen besseren haben. Welchen, habe ich noch nicht entschieden." } },
    friendly = { title = "Es spricht sich herum", { "Wusstet Ihr, dass die Goblins hier oben über Leute in anderen Städten reden? Ständig!" }, { "So funktioniert das Kartell. Es gibt vier Goblinstädte, die Bucht, Gadgetzan, Ratchet und uns. Sie liegen sehr weit auseinander und tratschen wie Nachbarn. Helft einer von ihnen, und die anderen hören mit der nächsten Karawane davon, und plötzlich sind die Goblins hier oben freundlicher zu Euch, als sie es je zu mir waren, und ich wohne schon ewig hier." }, { "Es macht mir nichts aus. Na gut, ein bisschen. Es ist aber schön, mit jemandem befreundet zu sein, den die ganze Stadt mag. Legacki hat mich erst gestern nach Euch gefragt. Ich sagte, Ihr wärt sehr nett und sehr mutig und furchtbar gut darin, Geheimnisse zu bewahren." }, { "Da fällt mir ein. Könnt Ihr ein Geheimnis bewahren?" } },
    honored = { title = "Der Plan", { "Versprecht, dass Ihr es niemandem erzählt. Versprecht es!" }, { "Ich werde einen Yeti bauen. Einen mechanischen, mit echtem Fell von Eisdistelyetis und den größten Hörnern, den schönen ungebrochenen, und Zahnrädern innendrin, und er wird direkt auf meine Freunde zugehen und ihnen einen Heidenschreck einjagen. Legacki hier, Sprinkle draußen in der Wüste und Quixxil im Krater. Allen dreien. Und dann, wenn sie aufgehört haben zu schreien, werden sie ihn sich richtig ansehen und sehen, wie gut er gemacht ist, und sie werden beeindruckt sein." }, { "Das ist der wichtige Teil. Das Schreien ist nur zum Spaß. Das Beeindrucktsein ist, was ich will." }, { "Ist das albern? Es ist ein bisschen albern. Ingenieurskunst ist das meistens, am Anfang." }, { "Und Ihr habt es geschafft! Ihr habt meinen Yeti zu jedem von ihnen getragen. Legacki hat ein ganzes Tablett fallen lassen. Sprinkle redet immer noch nicht mit mir. Ich glaube, das heißt, es hat funktioniert.", after = 5163 } },
    revered = { title = "Warum es wichtig war", { "Wenn meine Freunde einen Plan haben, hören alle zu. Wenn ich einen habe, lachen sie zuerst und hören danach zu, wenn sie überhaupt zuhören. Sie sind nicht gemein dabei. Das ist fast schlimmer. Sie finden es nur lustig, dass die Gnomin auch Ideen hat." }, { "Der Yeti war meine Antwort. Ich habe einen langen Winter damit verbracht, etwas zu bauen, worüber sie nicht lachen konnten, jede Spule daran, jeden Bolzen in seinem Kiefer. Ich wollte so sehr, dass sie aufhören zu lachen, dass ich eine Weile vergaß, Freude daran zu haben." }, { "Ich frage mich, für wen ich baue. Für die, die lachen, oder für die, die fragen. Legacki sagt, ich mache mir zu viele Gedanken über einen Yeti. Legacki hat noch nie etwas gebaut, das läuft. Die Antwort habe ich noch nicht gefunden. Ich bin aber näher dran." }, { "Ihr habt mir geholfen, und Ihr habt kein einziges Mal gelacht. Ihr habt gefragt, wie er funktioniert. Ihr wart vorsichtig mit den Hörnern. Daran musste ich mehr denken als daran, ob sie geschrien haben.", after = 5163 } },
    exalted = { title = "Ihr zuerst", { "Ich habe eine neue Idee. Eine gute. Sie ist auf der Werkbank aufgezeichnet, und es ist das Klügste, was ich mir je ausgedacht habe, und niemand auf der ganzen Welt weiß davon außer mir. Und jetzt Euch." }, { "Die Überraschung ist, dass ich sie Euch zeige, bevor ich sie meinen Freunden zeige. Früher bin ich immer zuerst zu ihnen gerannt, ganz außer Atem, und habe darauf gewartet, ob sie lachen würden. Das will ich nicht mehr. Ich will sie jemandem zeigen, der fragt, wie sie funktioniert." }, { "Die Leute fragen, warum eine Gnomin auf dem Dach der Welt wohnt. Die Wahrheit ist, dass die Kälte alle drinnen hält, beim Reden, und ich liebe das Reden, selbst wenn es um mich geht. In letzter Zeit ging es um Euch, und es stört mich nicht mehr, dass die Goblins Euch so sehr mögen. An manchen Tagen denke ich, sie haben einen besseren Geschmack, als ich ihnen zugetraut habe." }, { "Und jetzt könnt Ihr Euren eigenen Yeti bauen! Geht und erschreckt jemanden für mich. Jemanden, der es verdient hat.", after = 8798 }, { "Also. Sagt mir, was Ihr denkt. Und wenn es eine alberne Idee ist, sagt mir das auch. Ich traue es Euch zu." } },
  },
  [909] = {
    start = { title = "Hereinspaziert", { "Herein, herein, herein, hier ist Platz für jeden und Wunder im Überfluss!" }, { "Der Dunkelmond-Jahrmarkt hat diese ganze wunderbare Welt durchquert, um seine Zelte auf Eurer Wiese aufzuschlagen. Tiere vom Rand der Landkarte. Eine starke Frau, die hebt, was sich nicht heben lässt. Ein Mann, der sich an alles erinnert, was Ihr ihm je erzählt habt, und eine Wahrsagerin, die weiß, was Ihr noch niemandem erzählt habt." }, { "Kauft ein Los, esst etwas Frittiertes, verliert ein wenig Geld an den Spielen und gewinnt es am nächsten zurück. Niemand verlässt den Jahrmarkt so, wie er hereingekommen ist. Das ist ein Versprechen, und Silas Dunkelmond hält seine Versprechen, die meisten jedenfalls." } },
    friendly = { title = "Das Volk", { "Schon wieder da! Großartig. Gestattet, dass ich Euch die Familie vorstelle." }, { "Das ist Chronos, der nie etwas vergisst und Euch das auch sagen wird, ob Ihr fragt oder nicht. Yebb führt die Menagerie, in der nichts ganz so ist, wie das Schild sagt, und alles besser. Kerri Hicks biegt Euch eine Eisenstange. Rinling hat einen Blutschwur geleistet, jeden Gast zum Lächeln zu bringen, also lächelt Rinling an, ich flehe Euch an, ihm zuliebe." }, { "Und jeder von ihnen braucht etwas. Leder, gehämmerten Stahl, kleine surrende Apparate, die Felle von Dingen mit Zähnen, und diese seltsamen Karten, die in der Welt auftauchen und ein Deck sein wollen. Ein Jahrmarkt ist ein hungriges Geschöpf. Er frisst, was die Welt herstellt, und verwandelt es in Lose, und die Lose in Preise, und die Preise in Geschichten, die Ihr Euren Kindern erzählen werdet." }, { "Ihr habt ihn gut gefüttert. Die Familie hat es bemerkt." } },
    honored = { title = "Die Straße", { "Heute Nacht sind wir hier. Beim nächsten Mond sind wir fort." }, { "So lebt der Jahrmarkt. Wir bauen im Gras von Elwynn auf, unter den Eichen, und spielen für die Bauern und die Soldaten und die Kinder, die ihren Pflichten davongelaufen sind. Dann falten wir jedes Zelt, packen jede Kiste, locken jedes Tier in seinen Wagen und rollen nach Mulgore, wo die Tauren von den Klippen herunterkommen, um herauszufinden, was der Lärm soll." }, { "Ein Jahrmarkt, der an einem Ort bleibt, wird ein Markt, und ein Markt ist eine öde Sache. Wir bleiben nie. Manche meiner Leute wurden auf der Straße geboren und haben noch nie eine ganze Jahreszeit auf einer Wiese verbracht. Sie wüssten nicht, was sie mit einem Dach anfangen sollten." }, { "Die Wagen kennen den Weg inzwischen besser als ich. Elwynn, dann Mulgore, dann wieder Elwynn, und jedes Mal, wenn wir zurückkommen, sind dieselben Kinder ein wenig größer und tun so, als wären sie uns entwachsen." } },
    revered = { title = "Sayge", { "Hat Sayge Euch schon die Zukunft gelesen? Natürlich hat sie das. Sayge liest jedem die Zukunft." }, { "Sayge sagt, eine Zukunft sei nur das, was man ohnehin tun wollte, laut ausgesprochen. Ich glaube, sie hat recht. Ich glaube auch, dass es das Beängstigendste ist, was ich je in einem Zelt habe sagen hören, und ich habe sehr viele Dinge in Zelten sagen hören. Ihr Zelt ist das stillste auf dem Platz. Die Leute gehen lachend hinein und kommen nachdenklich heraus, und am nächsten Abend bringen manche von ihnen eine bessere Frage mit." }, { "Meine hat sie nie gelesen. All meine Jahre auf der Straße, und ich habe nicht eine einzige ihrer Fragen beantwortet. Ein Schausteller sollte nicht wissen, wie die Vorstellung endet. Er könnte anfangen, für das Ende zu spielen statt für die Menge." }, { "Ich habe die Straße gewählt. Niemand hat mich gezwungen. Ich hätte ein Haus und einen Garten und ein vernünftiges Handwerk haben können, und ich wählte einen Wagen und ein bemaltes Schild. Jeden Morgen wähle ich es aufs Neue. An manchen Morgen regnet es auf den Wagen, und ich wähle es trotzdem. Das sind die Morgen, die zählen." } },
    exalted = { title = "Wenn die Lichter ausgehen", { "Bleibt noch ein wenig. Der Letzte aus der Menge ist nach Hause gegangen." }, { "Das ist der Teil, den kein Los kauft, und es ist die beste Vorstellung, die ich habe. Hört zu. Die Laternen kommen eine nach der anderen herunter. Kerri hebt ihre eigene Hantelbank allein in den Wagen, weil sie es gern tut. Chronos zählt die Einnahmen und merkt sich jede Münze. Yebb singt den Tieren vor, bis sie schlafen. Rinling, endlich außer Dienst, lehnt an einem Wagenrad und lächelt niemanden an, und es ist das friedlichste Gesicht auf dem ganzen Jahrmarkt." }, { "Jeden Abend sage ich ihnen, dies sei die schönste Vorstellung, die es gibt, und jeden Abend meine ich die Zelte und die Lichter. Dies hier ist die andere. Die Familie, die sich wegräumt, müde und still und zufrieden." }, { "Ich rede zu viel. Das wird Euch aufgefallen sein. All das Hereinspaziert und das Staunen und das Wunder, so sage ich danke. Ich habe nie eine andere Art gefunden, und ich sage es Euch schon eine ganze Weile. Also, ein einziges Mal, ohne Trommeln: danke." }, { "Nun denn. Am Wagen steht eine Kiste mit Zeltheringen, und niemand hier bleibt für immer ein Gast." } },
  },
  [87] = {
    start = { title = "Der Geruch der Bucht", { "Ihr riecht nach der Bucht. Nach Steamwheedle-Münzen und Goblinseife." }, { "Jede Seele, die für Revilgaz Botengänge macht, ist ein Feind der Blutsegel, und für Feinde haben wir ein langes Gedächtnis und keine Geduld. Ich habe viele gekannt, die da anfingen, wo Ihr steht, und für die Goblins liefen, bis zu dem Tag, an dem sie neben das, was die Bucht zahlt, das legten, was die See zahlt, und nachrechneten." }, { "Die See ist ein weiter Ort. Die Bucht ist das Einzige auf ihr, das einem Blutsegel sagt, wo er nicht segeln darf. Eines Tages habt Ihr vielleicht genug von den Goblins. Es gibt ein rotes Schiff, das Hände anheuert, und niemand an Bord fragt, wo Ihr gewesen seid." } },
    friendly = { title = "Die zwei Kehlen", { "Na, sieh einer an. Die Schläger der Bucht greifen nach ihren Knüppeln, wenn Ihr hereinkommt. Gut. Das ist der erste ehrliche Empfang, den ein Goblin je jemandem bereitet hat." }, { "Ihr habt die Bucht lange bluten lassen, um hierherzukommen, und Ihr wisst, was es gekostet hat. Jede Goblinstadt hat Euren Namen inzwischen auf einer Liste, und nicht auf der, auf der Ihr ihn haben wollt." }, { "Ihr tragt die Farben gut. Der Mann, der sie vor Euch hatte, hat sie nie ausgefüllt, und jetzt hat ihn der Sturm.", after = 9272 }, { "Die Bucht hat zwei Kehlen, die zählen. Flottenmeister Seehorn, der ihre Schiffe auf dem Wasser hält, und den Baron, der ihr Gesetz an Land hält. Durchschneidet beide, und die Goblins lernen, dass es auf dieser See eine Flagge gibt, die sie nicht kaufen können." } },
    honored = { title = "Mannschaft", { "Wohlwollend, so. Herzlich wenige auf diesem Schiff haben es je so weit mit uns gebracht, und die meisten davon wurden in das Gewerbe hineingeboren." }, { "Ich nahm Euch als Messer an. Ein Messer ist ein nützliches Ding, und Ihr geht sorgsam damit um, und Ihr kommt zurück. Heute würde ich Euch das Steuerrad anvertrauen, und ich lasse nicht einmal meine eigene Mutter ans Steuerrad." }, { "Ihr habt getan, worum ich bat, beide, und seid aus der Bucht spaziert, um davon zu erzählen. Der Hut steht Euch, $gAdmiral:Admiralin;. Es gibt keinen zweiten wie ihn auf der See. Jedes Mal, wenn Ihr damit über Deck geht, steht die Mannschaft aufrechter, und sie haben keine Ahnung, dass sie es tun.", after = 4621 }, { "Manche gehen zurück, wisst Ihr. Alle paar Jahreszeiten bekommt einer der Meinen Heimweh nach sauberen Laken und Goblinbier, und die Bucht nimmt ihn wieder auf, gegen einen Preis, und wir nennen ihn danach einen Verräter. Ich verüble es ihnen nicht sehr. Die See ist hart zu den Leuten." }, { "Bevor sie gehen, gebe ich ihnen denselben Rat. Die Vergebung eines Goblins kostet Münzen. Die der See kostet nichts, und sie hat mich nie ein einziges Mal gebeten, mir die Stiefel abzuwischen." } },
  },
  [349] = {
    start = { title = "Der Pfad", { "Willkommen, willkommen, willkommen! Niemand findet dieses Haus aus Zufall, was bedeutet, dass entweder wir wollten, dass man Euch findet, oder meine Wachen nachlässig geworden sind, und ich werde vor dem Abendessen herausfinden, was davon." }, { "Ravenholdt ist ein Haus der feinen Hände. Diebe, Meuchelmörder, Leute, die einen Ring von einem Finger ziehen können, ohne dass der Finger etwas davon merkt. Wir haben natürlich unsere Fehden. Die Überbleibsel Alteracs haben sich Syndikat getauft, halten ihre Messer am falschen Ende und vermehren sich weiter." }, { "Ihr gehört nicht zu den Meinen, und ich könnte noch nicht sagen, was Ihr seid. Zeigt es mir, und tut es leise. Leise ist das, woran es mir immer fehlt." } },
    friendly = { title = "Embleme", { "Ah! Dem Syndikat fehlen in den Hügeln Männer, und ihre Embleme mit ihnen. Ich merke es immer." }, { "Jeder von ihnen trägt ein Emblem, und jedes verlorene Emblem ist eine kleine Schande für den Mann, der es trug. Die Klinge brauchen wir selten. Ein Mann des Syndikats, der sein Emblem verloren hat, hat bereits verloren, was zählte, und was ihn bei den Seinen erwartet, geht mich nichts an. Ich halte es für die hübscheste Arbeit, die dieses Haus je getan hat." }, { "Das ist unsere ganze Kunst, seht Ihr. Zuerst Feingefühl. Gewalt, wenn das Feingefühl versagt, und es versagt seltener, als jene glauben, die Gewalt bevorzugen. Jeder kann eine Kehle öffnen. Sehr wenige können in einer belebten Straße einen Geldbeutel öffnen und wieder schließen." }, { "Ihr habt diesem Haus gedient, und die Wachen winken Euch jetzt durch das Tor. So sieht in Ravenholdt ein Willkommen aus." } },
    honored = { title = "Schlösser", { "Also seid Ihr doch vom Fach. Ich ahnte es schon daran, wie Ihr dasteht." }, { "Ihr bringt Fahrad Kisten, höre ich. Schwere, störrische, hässliche kleine Kisten, und er setzt die Jungen daran, weil ein Schloss der ehrlichste Lehrer der Welt ist. Es kümmert sich nicht darum, wer Ihr seid, oder wer Euer Vater war, oder wie sehr Ihr wollt, dass es aufgeht. Es geht auf, wenn Eure Hände richtig sind, und keinen Augenblick früher. Ihr lasst in jeder ein paar Münzen, sagt man mir, damit die Jungen einen Grund haben, es weiter zu versuchen. Ermutigung nennt Fahrad das. Ich nenne es Köder, und ich heiße es gut. Man erzählt mir, ich sei einst ein schlechter Schüler darin gewesen. So habe ich es nicht in Erinnerung." }, { "Geduld und Hände. Alles andere, was wir lehren, ist Verzierung an diesen beiden. Die meisten, die in dieses Haus kommen, haben eines davon. Sehr wenige haben beides, und die, die es haben, sind die, die ich im Auge behalte. Euch behalte ich schon eine ganze Weile im Auge." } },
    revered = { title = "Der Beutel", { "Ich habe einmal etwas verloren." }, { "Einen kleinen blauen Beutel. Sein Inhalt ist meine eigene Angelegenheit und wird es bleiben. Diebe nahmen ihn, was Euch sagt, wie gut sie waren, und konnten ihn dann nicht öffnen, was Euch sagt, wie gut sie nicht waren. Also fanden sie einen Käufer für ein verschlossenes Rätsel, einen Schamanen in Azshara, der ihn für eine Reliquie hielt. Ein heiliges Ding ist, was immer der Kunde braucht. Dann starben die Diebe, wie es Leute tun, die mich bestehlen, und mir blieb ein Beutel, an den ich nicht herankam, und ein Schlüssel, der an einen schlimmeren Ort gelangt war, in den Hort eines grünen Drachen in einem versunkenen Tempel." }, { "Es war das eine Schloss, das ich nie in Ruhe lassen konnte. Ich wachte nachts auf, und meine Finger bewegten sich schon. Ich habe in meinem Leben sehr wenige Dinge auf diese Weise gewollt, und nie eines, das so klein war." }, { "Der Schlüssel kam mit Euch zurück. Ich öffnete ihn noch in derselben Nacht, allein, bei verschlossener Tür, und was darin lag, erhellte meine Hände. Ich blieb lange mit dem Licht auf ihnen sitzen, bevor ich jemanden hereinließ.", after = 8236 } },
    exalted = { title = "Der Schüler", { "Es gibt nichts mehr, was ich Euch lehren kann." }, { "Es ist der schwerste Satz in meinem Gewerbe, und ich habe ihn nie gern gesagt. Ein Meister ist nur so lange ein Meister, wie es einen Schüler gibt, der ihn braucht. Ihr braucht mich nicht. Eure Hände sind so gut wie meine, an manchen Tagen besser, und Eure Geduld hat jede Prüfung überdauert, die dieses Haus stellen konnte. Das ist das Beste, was Ravenholdt seit Jahren widerfahren ist, und ich meine es so, auch wenn es mich etwas gekostet hat, mich daran zu gewöhnen." }, { "Also gebe ich Euch stattdessen Arbeit. Im Hof ist ein Mädchen, nur Ellbogen und Nerven, das um nichts in der Welt eine Plunderkiste aufbekommt. Lehrt sie. Sie erinnert mich an jemanden, auch wenn ich Euch nicht sagen könnte, an wen. Lehrt mit Euren Händen, nicht mit meinen Worten. Meine wirken bei ihr nicht mehr, und ich vermute, Ihr werdet nicht viele brauchen." }, { "Und tragt, was ich Euch gab. Es hat sich in diesem Haus und in den Lagern des Syndikats herumgesprochen, und niemand hat es auf die Probe gestellt. In gewisser Weise schade.", after = 8236 }, { "Ich werde in der Halle sein und auf das Klicken aus dem Hof lauschen." } },
  },
  [471] = {
    start = { title = "Die Voliere", { "Achtet auf die Horste, und achtet auf Euren Kopf. Ein Greif, der Euch nicht kennt, reißt ihn Euch ab und denkt sich nichts dabei." }, { "Das hier ist Aerie Peak. Wir gehören nicht zur Allianz, wohlgemerkt. Unsere Türen stehen ihr offen und sind der Horde verschlossen, und das ist alles, was es dazu zu sagen gibt." }, { "Unser eigentlicher Ärger liegt näher. In diesen Hügeln wimmelt es von Trollen der Witherbark, und jeder von ihnen hätte einen Greifen lieber am Spieß als am Himmel. Dünnt sie aus, und Ihr werdet den Horst freundlicher finden. Den Greifen ist es so oder so gleich. Den Reitern nicht." } },
    friendly = { title = "Der beste Reiter", { "Ihr wart in den Hügeln fleißig. Die Reiter reden." }, { "Der beste Greifenreiter, den ich je hatte, war ein Kerl namens Rhapsody Shindigger. Niemand flog wie er. Ich schickte ihn einmal nach Süden, um einem von der Forscherliga zu helfen, und er kam mit einem Durst nach Hause, der nie wieder verging." }, { "Wir trinken hier oben alle, und gern. Rhapsody hörte auf, es gern zu tun. Ich musste ihn von den Vögeln nehmen, bevor er einen an den Suff verlor, und ich habe es dem Bier nicht verziehen, noch mir selbst, noch der Liga, obwohl das Letzte nicht gerecht ist. Mein Vater grub mit ihnen, in der Mannschaft, die Uldaman fand. Ich habe eine Schwäche für jeden, der nach Dingen sucht." }, { "Wenn also ein neuer Reiter zum Horst heraufkommt, messe ich ihn an Rhapsody. Noch keiner hat das Maß erreicht." } },
    honored = { title = "Scharfschnabel", { "Vor ein paar Tagen ist ein junger Greif verschwunden. Scharfschnabel. Der prächtigste junge Greif, den dieser Horst zu meiner Zeit ausgebrütet hat, der, von dem wir alle beschlossen hatten, dass er ihn eines Tages anführen würde." }, { "Er war mit seinen Eltern auf der Jagd und kam nie nach Hause. Trolle, das wussten wir, aber welche Trolle? Die Käfige der Witherbark wurden durchsucht und brachten nichts. Ebenso der Altar der Vilebranch, wo sie Schlimmeres tun, als Dinge in Käfigen zu halten. Das war die einzige gute Nachricht in einer schlechten Woche." }, { "Für uns ist ein Greif der halbe Reiter und die ganze Stärke des Clans. Verliert den besten der Jungen, und der ganze Horst wird still. Man konnte es hören. Niemand sang an jenem Abend beim Essen, und hier oben singt immer jemand." }, { "Ihr habt ihn heimgebracht. Seine Mutter und sein Vater haben seitdem nicht aufgehört, sich um ihn zu kümmern, und am ersten Abend, als die drei wieder zusammen im Horst waren, musste ich eine Weile hinter eine Säule gehen. Die Reiter waren so anständig, in den Himmel zu schauen.", after = 2994 } },
    revered = { title = "Der, der ging", { "Thadius Grimshade. Wahrsager. Lebt jetzt in Nethergarde, in den Verwüsteten Landen, unter Magiern und Schlimmerem. Er verließ den Gipfel vor langer Zeit, auf der Suche nach Wissen der dunkleren Sorte, und viele hier oben sagten, gut, dass er weg ist. Ich nie." }, { "Ein Zwerg kann den Horst verlassen und den Horst in sich behalten. Thadius hat es getan. Ich würde meinen Bart darauf verwetten, dass er zwischen all den Büchern eine Greifenfeder auf seinem Schreibtisch hat. Und ich wette, Rhapsody dreht immer noch den Kopf, wenn ein Greif über sein Lager fliegt. Man hört nicht auf, einer von uns zu sein, nur weil man fortfliegt, so wenig wie ein Greif aufhört, ein Greif zu sein, wenn der Gipfel außer Reichweite ist." }, { "Und als wir ihn brauchten, fand Thadius Scharfschnabel für uns, mit einer einzigen Feder und welchen dunklen Künsten auch immer, die er in Nethergarde betreibt. Er bat nicht um Dank. Ein Wildhammer täte das nicht.", after = 2993 }, { "Ich frage mich in letzter Zeit, wie Ihr Euch auf einem Greifen machen würdet. Ich habe das Gefühl, Ihr wärt gut. Mehr als gut. Es wäre schön, das eines Tages herauszufinden, während der ganze Horst so tut, als wäre ihm gleich, wie es ausgeht." } },
    exalted = { title = "Hinauf", { "Mein Vater verbrachte sein ganzes Leben damit, nach unten zu graben. Uldaman, und jedes Loch, in das die Liga ihn je seinen Bart stecken ließ. Ich verbrachte meines damit, nach oben zu gehen. Wir stritten darüber beim Bier, in welcher Richtung die Wahrheit liegt, unter dem Stein oder über den Wolken. Keiner von uns gewann." }, { "Er hätte Euch gemocht. Ihr sucht, so wie er. Ihr kämpft für das, was unser ist, so wie ich es mir wünschen würde. Die Hügel sind Euretwegen ruhiger, die Trolle weniger, und die Reiter erzählen im Horst Geschichten über Euch, von der guten Sorte." }, { "Letzte Woche ging ich hinaus zu Rhapsodys Lager. Zum ersten Mal, seit ich ihn gehen ließ. Er steckte halb in einem Fass, wie immer. Ich erzählte ihm von Euch. Er lachte und sagte, es klinge, als hätte ich noch einen gefunden." }, { "Ich sagte ihm, es werde nie einen zweiten geben. Dann sagte ich ihm, ich hätte all diese Jahre gebraucht, und Euch, um aufzuhören, jeden an ihm zu messen. Darauf sagte er nichts. Er goss mir stattdessen einen Becher ein, und ich trank ihn mit ihm, und ausnahmsweise war es ein guter Schluck zur rechten Zeit." }, { "Fliegt gut, wohin Ihr auch geht. Die Trolle sind weniger. Fort sind sie nicht." } },
  },
  [92] = {
    start = { title = "Gelkiserde", { "Ihr steht auf der Erde der Gelkis, und sie kennt Euch nicht." }, { "Ich höre die Erde. Sie sagt mir, wer auf ihr geht, und wie schwer, und was er im Herzen trägt. Euch kann sie noch nicht lesen, also gibt es für Euch keinen Platz an unseren Feuern." }, { "Die Magram sind unsere Feinde. Sie sind laut, und sie glauben, ihre Stärke genüge. Die Erde ist stärker als Stärke. Wenn die Erde Euren Namen kennt, werde ich mit Euch sprechen. Bis dahin geht zurück, woher Ihr gekommen seid." } },
    friendly = { title = "Was die Erde sagt", { "Die Erde ist jetzt schwer von Magram, und Ihr seid es, $gder:die; sie schwer gemacht hat. Das ist gut. Jetzt werden wir reden." }, { "Hört zu. Die Gelkis kämpfen nicht nur mit Speeren. Wir kämpfen mit dem, was der Boden uns gibt. Wir glauben, dass die Mutter der Zentauren, Theradras, unter diesem Land liegt und dass die Erde ihre Stimme ist. Wir bewahren ihre Tränen in unserer Höhle, und solange wir sie bewahren, bewahrt sie uns." }, { "Die Magram sagen, niemand beschütze die Zentauren. Sie sagen es laut, und sie hören auf nichts. Also werden sie verlieren. Ein Clan, der auf nichts hört, hat nichts, das ihn warnt, wenn der Boden sich verschiebt." }, { "Ihr gehört nicht zu den Gelkis. Ihr werdet nie dazugehören. Aber die Erde bebt nicht mehr, wenn Ihr zu unserem Dorf hinaufsteigt, und bei meinem Volk ist das das erste Wort der Freundschaft." } },
    honored = { title = "Warum Ihr kamt", { "Die Erde hat mir ein Geheimnis über Euch erzählt." }, { "Euer Volk kam nach Desolace, um zu lernen, wie man die Zentauren schlägt. Ihr habt die Gelkis gewählt, weil wir die Magram hassen, und Hass ist eine Tür. Wenn die Magram schwach sind, wird Euer Volk sich gegen die Gelkis wenden, und es wird schon wissen, wie man uns bricht. Ich wusste es von Anfang an. Ich ließ Euch trotzdem kommen." }, { "Die Erde lügt nicht, aber sie wählt nicht. Ich wähle." }, { "Vor nicht langer Zeit kam ein roter Kristall in unsere Erde, aus einem zerbrochenen Land weit jenseits dieses Himmels, einem Land der Dämonen. Er ist neu, und fremd, und stark, und die Erde weiß noch nicht, was er tun wird. Ihr seid wie dieser Kristall." }, { "Khan Jehn lehnte sich an seine Stärke wie an eine Mauer, und die Erde ist geduldig mit Mauern. Eure Hände haben sie eingerissen, für uns.", after = 1374 }, { "Wenn Euer Volk kommt, um die anderen Clans zu brechen, soll es die Gelkis stehen lassen. Das ist alles, was ich von ihm verlange. Von Euch verlange ich nichts mehr. Ihr seid $gein Freund:eine Freundin;. Ich sage es und weiß, was ich weiß." } },
  },
  [93] = {
    start = { title = "Stark", { "Geht weg. Die Magram töten die Schwachen, und ich weiß noch nicht, was Ihr seid." }, { "Die Gelkis beten zu einer Mutter unter dem Boden. Sie denken, sie beschützt sie. Niemand beschützt die Zentauren! Niemand hat die Zentauren je beschützt. Wir beschützen uns selbst, mit Hufen und Speeren, und die Magram beschützen sich am besten von allen, weil wir die Stärksten sind." }, { "Ihr wollt mit Warug reden? Tötet Gelkis. Dann kommt wieder, und ich werde wissen, was Ihr seid." } },
    friendly = { title = "Lachen", { "Ha! Ihr habt viele Gelkis getötet. Ihre Späher spucken jetzt Euren Namen aus, mit derselben Spucke, die sie für uns aufheben. Gut!" }, { "Ihr seid $gkein Zentaur:keine Zentaurin;, aber Ihr kämpft ein bisschen wie einer. Lacht Ihr, wenn Ihr kämpft? Das solltet Ihr. Ein Krieger, der lacht, zeigt dem Feind, dass der Feind klein ist, und der Feind glaubt es, und dann ist er klein. So kämpfen die Magram. Die Gelkis singen für Steine. Wir lachen, und wir gewinnen." }, { "Die Gelkis bewahren Kristalle in einer Höhle und nennen sie die Tränen der Mutter. Tränen! Wenn sie zerbrochen werden, kommt die Mutter nicht. Sie kommt nie. Eines Tages zerbreche ich jeden davon, und die Gelkis wissen endlich, was die Magram schon wissen." }, { "Jetzt reden wir, Ihr und Warug. Bringt mir etwas zum Lachen." } },
    honored = { title = "Der kleine Holzmann", { "Einmal kam ein Gnom, nicht größer als ein Kind, hinter seinen Pferden aus dem Staub, mit einem Karren voller Spielzeug. Feuer in Farben. Kleine Maschinen, die ohne Atem weiterliefen. Er war das Lustigste, was ich je getroffen habe. Ich habe ihn getötet. Zuerst hat er mich zum Lachen gebracht. Ich erinnere mich." }, { "Das Spielzeug, das mir am liebsten war, habe ich behalten. Einen Holzmann mit einer Hand, die rauf und runter ging. Hallo, hallo, hallo. Eines Tages schlug ich ihn, und er zerfiel in meiner Faust. Es tat mir leid. Warug tut nie etwas leid. Der kleine Holzmann tat mir leid." }, { "Ihr habt mir einen neuen gebracht. Ich habe ihn bewegt. Er steht in meinem Zelt, und ich schlage ihn nicht. Ich bin stark genug, es nicht zu tun.", after = 1371 }, { "Shaka ist tot, durch Eure Hand. Sein Kopf steckt auf einem Pfahl vor meiner Tür, wo Shaka lernen kann, was die Magram sind.", after = 1375 }, { "Ihr seid stark, also sage ich es Euch. Die Magram werden über Desolace herrschen, und die anderen Clans werden unter unseren Hufen sein. Ich mag Euch. Ich mag laute Dinge, und Kämpfe, und den kleinen Holzmann. Jetzt mag ich Euch auch." } },
  },
  [2778] = {
    start = { title = "Der leere Himmel", { "Seht hinauf. Höher. Ihr seht die kleinen Luftwesen um die Insel treiben und denkt, die Winde leisten uns noch Gesellschaft. Sie tragen nur die Gestalt der Winde. Die Geister, die mein Volk zum Himmelswall trugen, die mit uns sprachen und diese Insel trugen, schweigen seit langer Zeit." }, { "Die Windformer haben geschworen herauszufinden, wohin sie gegangen sind, und sie zurückzuholen, was es auch koste und wie weit hinab der Weg auch führe. Geht ihn mit uns, oder geht ihn irgendwo, wohin mein Wort Euch nicht folgt." } },
    friendly = { title = "Was wir schulden", { "Ihr seid geblieben. Dann steht Euch die Wahrheit darüber zu, was es heißt, an der Seite der Windformer zu stehen." }, { "Die Geister gaben uns ihre Gaben, Instrumente wie Konstrukte, und wir pflegen sie noch immer. Wir lesen den Wind, denn der Wind ist das Letzte von ihnen, das sich noch bewegt. Und wir beobachten das Land. Es öffnet sich, die Leylinien steigen durch es empor, und unser Wort dafür lautet: Narben. Die Magister des Hohen Ordens würden lieber eine Narbe studieren, als zu fragen, was sie verursacht hat." }, { "Die Al'Aketh beobachten wir nicht. Wir antworten ihnen, jedes Mal. Das schwäche ich für niemanden ab." }, { "Was Ihr für uns tut, ist kein Gefallen. Es ist ein Teil einer Schuld, und die Schuld ist unsere." }, { "Der Schrein ist gefallen, und seine Priesterin ist geflohen. Was diese Insel vor dem Windlord schützte, ist nun fort. Ich lese jede Nacht den Himmel. Bisher hat er nur zurückgeblickt.", after = 93836 } },
  },
  [2779] = {
    start = { title = "Was wir vergaßen", { "Ihr findet uns suchend. Ein Orden von Gelehrten, der das meiste von dem verloren hat, was er wusste, tut kaum etwas anderes." }, { "Wir sind jetzt allein. Die Winde, die mein Volk zum Himmelswall trugen, sind fort, und ich sage es offen, weil der größte Teil der Insel es noch immer nicht kann. Einst waren wir Gelehrte der Hochgeborenen, und irgendwo in den langen Jahren seither vergaßen wir, wie man irgendetwas tut, das die Winde nicht für uns taten. Der Hohe Orden gedenkt, sich zu erinnern." }, { "Hier gibt es Arbeit für jeden, der bereit ist zu suchen." } },
    friendly = { title = "Unter uns", { "Manche kommen zum Hohen Orden, weil sie hineingeboren wurden, manche aus eigener Wahl, und ich habe aufgehört zu fragen, was davon. Was zählt, ist, was Ihr daraus macht." }, { "Wir suchen, was unsere Vorfahren wussten, bevor die Winde das Wissen unnötig machten: das Arkane von Eldre'Thalas, eine Stärke, die von niemandes Güte abhängt. Ein Erzmagier der Kirin Tor in Dalaran beantwortet meine Briefe, was mehr ist, als die Winde seit langer Zeit getan haben. Azeroth hat weitergelernt, während wir dahintrieben. Es wird uns lehren, wenn wir demütig genug sind zu fragen." }, { "Die Windformer halten uns für leichtsinnig. Ihr werdet sie das sagen hören. Hört sie an, dann kommt hierher zurück und tut die Arbeit trotzdem." }, { "Ich schickte Belathaan zum Schrein, um zu reden. Ich war sicher, dass Reden möglich sei. Seitdem war ich mir in sehr wenigem sicher, und ich merke, dass ich so besser arbeite.", after = 92834 } },
  },
  [730] = {
    start = { title = "Rekruten", { "Name, Sippe und Handwerk, auf die Liste. Der Schreiber liest sie später, oder ich." }, { "Ich werbe Soldaten für die Stormpikegarde an, und ich brauche sehr viele davon. Das Tal frisst Soldaten wie eine Esse Kohle. Man geht hinein, man kämpft, man kommt wieder heraus, oder nicht, und ich werbe den Nächsten an. Das ist die Arbeit. Ich bin gut darin." }, { "Jeder Soldat der Garde trägt ein Abzeichen, und das Abzeichen wächst mit dem Soldaten. Zeigt mir auf dem Feld, woraus Ihr gemacht seid, und ich sorge dafür, dass Ihr ein besseres bekommt. Verliert es, und ich finde Euch ein anderes. Ich habe immer mehr." } },
    friendly = { title = "Erster Rang", { "Steht Ihr noch, $gSoldat:Soldatin;? Das ist mehr, als die meisten sagen können." }, { "Ihr würdet staunen, wie viele es nie so weit schaffen. Sie kommen voller Lieder die Straße herauf, marschieren ins Tal, und das ist das Letzte, was ich von ihnen sehe. Viele kommen nie weiter als bis zu einem Namen auf einer Liste. Ihr schon." }, { "Da. Steckt das an. Rang, $gSoldat:Soldatin;, ein besserer als der letzte. Macht ihn nicht zum Lügner.", after = 7168 }, { "Niemand sagt den Neuen, wofür das Abzeichen ist. Es ist dafür, dass der Soldat neben Euch weiß, dass Ihr schon einmal standgehalten habt. Das ist alles. Ein Zwerg im Schneesturm, auf den ein Frostwolf zukommt, will wissen, ob der Fremde an seiner Schulter davonläuft. Das Abzeichen zeigt, dass Ihr es nicht tut." }, { "Ich halte hier einen Rang für jeden Soldaten bereit, der sich einen verdient hat, und danach einen besseren." } },
    honored = { title = "Das Ohr des Königs", { "Die Kunde von Euch ist den Berg hinaufgegangen. Ganz hinauf." }, { "Das Lager redet, und das Lager schreibt nach Hause, und einiges von dem, was es schreibt, zwischen den Klagen über die Suppe, erreicht den König selbst. Euer Name tat es. Ich habe sehr viele Soldaten in dieses Tal geschickt, und der König hört von sehr wenigen von ihnen." }, { "Er will dieses Tal. Das hat er uns allen klargemacht, in Briefen mit sehr viel Siegel darauf. Jeder Soldat, den ich hineinschicke, ist ein Stück dessen, was er will, und die meisten, es tut mir leid, das zu sagen, sind aufgerieben oder fort, bevor er je erfährt, wie sie hießen." }, { "Ihr kommt Schlacht um Schlacht heil nach Hause, und Ihr geht wieder hinein. So kommt ein Name einen Berg hinauf." }, { "Nehmt das neue Abzeichen. Der König kennt jetzt Euren Namen, also tragt es dort, wo er davon hören wird.", after = 7169 } },
    revered = { title = "Der Troll, der nicht tot bleiben wollte", { "In diesem Tal gibt es eine dritte Seite." }, { "Die Trolle der Winterax. Menschenfresser, oben in den Höhlen, und Zwerge würden in ihren Kochtöpfen landen, hätten sie die Gelegenheit. Ihr Häuptling war ein Rohling namens Korrak. Wir haben ihn getötet. Gut. Dann brachten die Trolle ihn zurück, wie Trolle es tun. Verbrennt den Leichnam, sage ich immer, wenn ein Troll fällt. Diesen hat niemand verbrannt." }, { "Ein Krieg hat mehr als zwei Seiten, und die, die man vergisst, sind die, die einen erwischen. Ich habe gute Soldaten an einen Speer aus den Höhlen verloren, während sie mit der Burg beschäftigt waren. Behaltet die Frostwölfe im Auge, und behaltet die Höhlen im Auge. Den Trollen ist gleich, welche Flagge Ihr tragt. Einem Kochtopf auch." }, { "Ihr seid bei der Garde jetzt Ehrfürchtig. Über diesem gibt es noch mehr Rang, und ich würde ihn gern einem Soldaten anstecken, der es wert ist." }, { "Tragt das neue Abzeichen so stolz in die Höhlen wie aufs Feld.", after = 7170 } },
    exalted = { title = "Befehl", { "Ich habe sehr viele Abzeichen ausgegeben. Das letzte davon ist das Auge der Führung, und Ihr seid ihm so nah, wie man ihm als $gSoldat:Soldatin; kommt." }, { "Da ist es. Tragt es, und die Soldaten auf diesem Feld werden befolgen, was Ihr ihnen sagt, solange die Schlacht dauert. Sie werden Euch fragen, wo sie stehen sollen, und Ihr werdet es jedes Mal wissen müssen.", after = 7172 }, { "Als Ihr zum ersten Mal diese Straße heraufkamt, warb ich Euch an, wie ich jeden anwerbe, ein Name mehr für die Liste, eine Nadel mehr auf der Karte. Ich habe nicht zweimal darüber nachgedacht." }, { "Ich habe meinen ganzen Dienst damit verbracht, Soldaten zu sagen, wohin sie gehen sollen. Man wird gut darin. Man wird so gut, dass man nicht mehr merkt, dass es Leute sind, die man herumschiebt. Dann fangen die Soldaten an nachzusehen, welchen Weg eine der Nadeln gegangen ist, bevor sie ihren eigenen wählen, und man fängt wieder an, es zu merken." }, { "Also geht und gebt da draußen Eure Befehle, und gebt sie gut. Ich werde am Eingang des Tals mit den Ersatzabzeichen sein, und wenn Ihr einen Befehl für einen alten Werber habt, nehme ich ihn an. Es ist lange her, dass mir jemand einen gab, über den ich froh war." }, { "Geht schon. Sie warten auf Euch." } },
  },
  [729] = {
    start = { title = "Der Ruf", { "Ihr seid ins Tal gekommen. Gut. Kommt aus dem Wind, $gFremder:Fremde;." }, { "Lange Zeit gab es hier keinen Krieg. Die Frostwölfe jagten und zogen ihre Jungen groß und begruben ihre Alten, und die Berge beschützten uns. Jetzt sind die Zwerge mit ihren Bannern über die Berge gekommen, und die Hörner erklingen wieder im Tal, und jeder Orc dieses Clans spürt es in der Brust." }, { "Auf diesem Feld wird nichts verteilt. Welche Ehre Ihr auch habt, Ihr tragt sie selbst davon. Kämpft für die Frostwölfe und kommt zu mir zurück, und ich werde Euren Namen lernen." } },
    friendly = { title = "Erwacht", { "<Laggrond salutiert vor Euch.>" }, { "Ihr seid vom Feld zurückgekommen, und Ihr kamt als $gSoldat:Soldatin; zurück. Ich erkenne es daran, wie Ihr dasteht." }, { "Nehmt dieses Abzeichen und tragt es immer. Darauf steht: Freund des Clans.", after = 7163 }, { "Diese Hitze in Euren Händen da draußen, das erste Mal, als die Hörner bliesen und Eure Füße sich bewegten, bevor Ihr es ihnen befahlt, das ist Euer Geist, der antwortet. Manche nennen das Furcht. Es ist der älteste Teil von Euch, der sich erinnert, wofür er da ist." }, { "Der Clan hat ein Wort für einen Soldaten, der so zurückkommt: Freund. Er gibt dieses Wort nicht leichtfertig. Der Clan ist klein und alt in diesen Bergen, und er erinnert sich an jede Hand, die für ihn erhoben wurde." } },
    honored = { title = "Der Zorn", { "Mein Volk hat nie vom Blut des Dämons getrunken. Darauf bin ich jeden Tag meines Lebens stolz." }, { "Und doch, wenn die Hörner in diesem Tal erklingen, antwortet etwas in mir, und die Antwort gefällt mir nicht. Der Kampfrausch. Er steigt langsam in einem alten Orc, aber er steigt. Mein Puls schwer in den Ohren, die Kälte aus meinen Händen verschwunden. Eine Weile gibt es nichts als den nächsten Schlag, und den nächsten, und es ist das Beste, was ich seit Jahren gefühlt habe." }, { "Darum halte ich ihn an einem kurzen Strick. Ein Clan, der den Dämon zurückwies, darf den Zorn nicht um seiner selbst willen lieben lernen. Ich sage das jedem Soldaten, der diesen Rang erreicht, und die meisten vergessen es bis zur nächsten Schlacht." }, { "Das nächste Abzeichen ist Eures. Haltet den Strick kurz und erinnert Euch, wer ihn hält.", after = 7164 } },
    revered = { title = "Geschichten", { "<Laggrond brüllt.>" }, { "Man erzählt Geschichten über Euch, $gSoldat:Soldatin;. In der Burg, an den Feuern, auf den Türmen. Selbst jenseits des Schnees, sagt man, werden die Zwerge still bei Eurem Namen." }, { "Geschichten sind etwas Gutes für einen Clan. Sie machen die Jungen tapfer. Niemand sagte mir, was sie mit dem machen, über den sie erzählt werden. Sie machen, dass man mehr davon will. Den nächsten Kampf größer, die nächste Geschichte lauter. Ein Krieger, der für die Geschichte kämpft, ist einen Sturmangriff von einem Grab entfernt, an das sich niemand erinnert." }, { "Der Clan erzählt noch eine über einen jungen Orc, der allein hinter einem großen Bären in den Schnee ging und mit seinem Fell heimkam. Er erzählt nicht, dass die Gefährtin des Bären den Pass herunterkam, während er über dem Fell kniete und es bewunderte, und dass sein Bruder, der ihm hinaus gefolgt war, sich ihr in den Weg stellte. Der Bruder überlebte. Er ging nie wieder wie zuvor. Der junge Orc war ich. Wenn der Clan sie am Feuer erzählt, erzähle ich die zweite Hälfte, und mein Bruder nickt." }, { "Haltet die Geschichte klein." } },
    exalted = { title = "Der kühle Kopf", { "Drek'Thar spricht von Euch. Laut, vor den Ältesten, wo alle es hören können. Einer der Ältesten fragte mich hinterher, ob Ihr im Kampf wirklich so kalt seid, wie die Soldaten sagen. Ich sagte ihm, kälter." }, { "Das Auge der Führung wird bald Eures sein, und die Soldaten des Tals werden Eurem Wort folgen." }, { "Da. Das Auge ist Eures. Sie werden gehen, wohin Ihr sie schickt, und sie werden darauf vertrauen, dass Ihr sie dorthin schicken wolltet.", after = 7167 }, { "Wenn die Hörner blasen, steigt in den meisten von uns das Rot auf. In Euch wird es still, und Ihr wägt die Türme und die Burg und das Gelände dazwischen ab, und wählt. Das ist seltener als Mut und weit seltener als Zorn. Ich habe von beidem viel gekannt, und den Zorn habe ich von innen gekannt." }, { "Noch etwas. Ihr wisst, was eine Schlacht die kostet, die das Banner tragen, und Ihr geht trotzdem. Geht also und bringt so viele heim, wie Ihr könnt. Die Jungen werden Euch jetzt überallhin folgen, und wenn sie dort ankommen, sollen sie finden, dass es das Gehen wert war. Ein Orc, der einmal einem guten Anführer gefolgt ist, wird dem nächsten besser folgen." }, { "<Laggrond salutiert.>" }, { "Ein kühler Kopf und ein warmes Herz. Mehr verlangen die Frostwölfe nicht." } },
  },
  [890] = {
    start = { title = "Wenige Worte", { "Ihr gehört zur Allianz. Für die Schlucht genügt das." }, { "Ich bin Farsong. Ich sichere die Straße dorthin, mit meinen Schwestern der Silverwing. Die Orcs sichern die Straße auf der anderen Seite. Zwischen uns liegt ein Tal, das einmal Wald war, und sehr viel Kampf." }, { "Ich sage nicht viel. Ihr werdet Euch daran gewöhnen. Kämpft an unserer Seite und bringt mir, was Ihr dort drinnen verdient, und wir werden herausfinden, ob Ihr bleibt. Vertrauen ist langsam, in Ashenvale. Die Bäume haben uns das gelehrt." } },
    friendly = { title = "Die Bäume", { "Ihr wart in der Schlucht." }, { "Jedes Abzeichen, das aus der Schlucht zu mir kommt, ist ein Kampf, den jemand überlebt hat. Ich halte es einen Augenblick, bevor es zu den anderen kommt. Meine Schwestern nennen es ein Ritual. Ich weiß gern, was ein Ding wiegt, bevor ich ihm traue, und ein Abzeichen wiegt genau das, was es gekostet hat." }, { "Die Orcs sind laut, und sie mögen es so. Ich musste nie mit ihnen mithalten." }, { "Meine Schwestern sagen, ich rede mit den Bäumen. Das tue ich nicht. Ich höre ihnen zu, und das ist etwas anderes, und sie haben mehr zu sagen als die meisten Leute, die auf dieser Straße an mir vorbeigehen." } },
    honored = { title = "Die Stümpfe", { "Ich ging durch dieses Tal, als es Wald war." }, { "Am anderen Ende stand eine Eiche, dort, wo jetzt das Sägewerk der Orcs ist, älter als alles, was ich kannte. Eine Eulenfamilie lebte darin. Ich lebte einmal eine ganze Jahreszeit in ihren Zweigen und tat gar nichts. Damals hatte niemand Eile." }, { "Die Äxte kamen nachts, beim ersten Mal. Am Morgen war da eine Spur durch die Farne, und am Ende jenes Jahres war da ein Sägewerk. Die Eulen gingen im Frühling danach. Ich weiß nicht, wohin sie gegangen sind. Ich habe an jeder alten Eiche zwischen hier und Astranaar nach ihnen gelauscht, und ich habe sie noch nicht gehört." }, { "Ein großer Teil des Tals sind jetzt Stümpfe. Die Orcs sagen, sie brauchten das Holz. Vielleicht taten sie das. Ich habe es nicht vergeben, und ich habe es nicht vor. Es ist still in mir, und es wird den Krieg überdauern." } },
    revered = { title = "Die Gleve", { "Eine meiner Schwestern fiel letzten Frühling am anderen Ende der Schlucht. Sie lief allein auf ihr Banner zu, weil sie schnell und jung und sicher war. Sie war schnell. Sie war jung. Sie irrte sich. Sie hatten genau darauf gewartet, hinter der Mauer ihrem Sägewerk, und sie mussten nicht schnell sein." }, { "Ich trug ihre Gleve heim. Sie hängt in meinem Zelt. Ich reinige sie einmal in jedem Mond. Sie braucht es nicht. Die Schneide ist noch schartig, wo sie die erste Axt parierte, und ich habe die Scharte nie ausgefeilt. Niemand fragt, wessen sie ist. Schildwachen fragen einander das nicht. Ihren Namen behalte ich. Das tun wir mit den Namen der anderen, wenn der Rest fort ist." }, { "Ihr wart lange genug in dieser Schlucht, um zu wissen, was es kostet, auf ihr Banner zuzulaufen. Ich versuchte, sie Geduld zu lehren, einen ganzen Sommer lang. Sie war schneller als mein Lehren." } },
    exalted = { title = "Die Eichel", { "Letzte Nacht ging ich ans andere Ende der Schlucht, zum Stumpf der alten Eiche neben ihrem Sägewerk, während die Orcs schliefen. Der Boden dort ist hart, flach getreten von ihren Stiefeln. Ich grub mit den Händen an seinem Fuß, den größten Teil der Nacht, und eine ihrer Wachen ging an mir vorbei und hörte nichts. Ich legte eine Eichel in das Loch, eine von der alten Eiche selbst, die ich aufbewahrt hatte. Dann füllte ich es zu. Es ist ein kleines Loch. Ihr würdet daran vorbeigehen." }, { "Neben die Eichel legte ich ein Abzeichen, das erste, das mir je gebracht wurde. Ich hatte es lange von den anderen getrennt aufbewahrt, ohne zu wissen, wofür. Jetzt weiß ich es." }, { "Sie wird nicht wachsen, solange gekämpft wird. Selbst wenn, würden sie sie fällen. Das weiß ich alles. Ich habe es trotzdem getan." }, { "Eines Tages wird das Kämpfen aufhören, und am anderen Ende der Schlucht wird ein Baum stehen, für den niemand eine Verwendung hat. Er wird lange brauchen, um zu wachsen. Eichen tun das, und ich habe gelernt, auf sie zu warten. Wenn Ihr danach dort vorbeikommt, lauscht nach Eulen. Sie werden den Baum kennen. Eulen tun das immer." } },
  },
  [889] = {
    start = { title = "Zug zug", { "Zug zug, $gFreund:Freundin;! Kelm Hargunth, der die Vorhut satt und heil hält, zu Euren Diensten, oder ich werde es sein, sobald Ihr etwas für sie getan habt." }, { "So läuft das hier. Ihr kämpft in der Schlucht, die Vorhut lernt Euch kennen, und je besser sie Euch kennt, desto mehr von meinem Bestand darf ich Euch verkaufen. Rationen, Verbände, das gute Zeug, alles für die Schlucht gemacht und sonst nirgends zu gebrauchen." }, { "Fürs Erste repariere ich Eure Ausrüstung. So viel tue ich für jeden in Rot. Dann geht hinein, macht den Elfen einen harten Tag und holt Euch Appetit." } },
    friendly = { title = "Rationen", { "Da seid Ihr ja! Die Vorhut kennt jetzt Euer Gesicht. Das heißt Rationen." }, { "Hier. Reisebrot, Trockenfleisch, ein kleines Etwas für die Nerven, alles für die Schlucht gepackt. Außerhalb der Schlucht nützen sie niemandem, also hebt sie nicht für eine lange Reise auf. Sie sind dafür gemacht, zwischen einem Kampf und dem nächsten gegessen zu werden, im Stehen, mit einem Elfenpfeil im Pfosten neben Eurem Kopf." }, { "Der halbe Krieg ist, wer zuletzt gegessen hat, und über diese Hälfte singt niemand. Ein Orc mit etwas im Bauch hält eine Flagge eine ganze Weile länger als einer ohne. Ich kann keine Axt mehr schwingen wie früher. Ich kann dafür sorgen, dass die, die es tun, nicht hungrig sind." }, { "Esst. Geht kämpfen. Das Brot wird hier sein." } },
    honored = { title = "Verbände", { "Damit stehen Euch also die Verbände offen. Nicht, dass ich sie so gern verkaufe wie das Brot." }, { "Jeder Verband, den ich verkaufe, kommt auf jemanden, den ich kenne. Das ist das Problem, wenn man der Versorger ist. Man verteilt die Rationen im ersten Licht, und bei Dunkelheit kommen dieselben Gesichter wegen Leinen zurück, und manche kommen gar nicht zurück. Ich weiß, ohne zu fragen, wer ein neues Bündel braucht und wer gar nichts mehr braucht." }, { "Die Elfen sind keine leichten Gegner. Sie kennen diesen Wald besser, als wir es je werden. Sie kommen schnell und leise aus den Bäumen, und sie geben nicht auf, niemals, weil es ihre Bäume sind, und ich würde für meine genauso kämpfen." }, { "Also, Verbände. Kauft eine Menge davon und verteilt sie. Die neben Euch werden sie vor Euch brauchen." } },
    revered = { title = "Höllschreis Clan", { "Jeder Orc der Vorhut kann Euch von Grom erzählen. Die meisten erzählen es lauter als ich, und sie lassen die Mitte weg." }, { "Die Warsong sind Höllschreis Clan. Als die Horde über das Meer kam, schickte uns der Kriegshäuptling wegen des Holzes hierher, und Grom übernahm die Arbeit, und der Wald wehrte sich, und Grom tat Dinge, um zu gewinnen, für die die ganze Horde bezahlt hat. Dann bezahlte er am Ende selbst dafür, mit seinem Leben, und befreite uns alle dabei. Wir besingen ihn. Wir sind stolz auf ihn. Wir kennen auch den Preis." }, { "Und die Äxte haben nicht aufgehört. Das Holz ist immer noch gefragt. Jeder Baumstamm, der dieses Tal verlässt, kostet jemanden, einen Elfen oder einen Orc, und ich kenne einige der Namen auf unserer Seite. Die Elfen kennen ihre." }, { "Ich habe einmal mein Abendessen auf einem ihrer Baumstümpfe gegessen, und er gab einen guten Tisch ab. Seitdem habe ich dort nicht mehr gegessen." } },
    exalted = { title = "Etwas, das nicht zum Töten ist", { "Die Vorhut fragt nicht mehr, wer Ihr seid. Ich würde sagen, das habt Ihr Euch verdient, aber es ist ein kleines Wort dafür." }, { "Eines Tages will ich etwas verkaufen, das nicht zum Töten ist. Lampen. Gute Stiefel zum Gehen, nicht zum Rennen. Angelschnur. Spielzeug für die Jungen des Clans, die Sorte, die nur Lärm macht. Eine Wiege oder zwei, geschnitzt aus Holz, um das niemand kämpfen musste." }, { "Ich verkaufe der Vorhut schon so lange Rationen und Verbände und Reparaturen, dass ich vergessen habe, wie es ist, jemandem etwas in die Hand zu geben und mich nicht zu fragen, ob er lange genug lebt, um es aufzubrauchen." }, { "Mein Wunsch wird nicht bald in Erfüllung gehen. Das weiß ich. Die Schlucht geht nirgendwohin, und die Elfen auch nicht, und wir auch nicht." }, { "Jeder von Euch, der aus dieser Schlucht herausgeht, ist eine kleine Übung für den Morgen, den ich will." }, { "Eines Tages will ich diesen Ladentisch an einem Morgen öffnen, an dem niemand verletzt hereinkommt. Ich hatte noch nie einen. Nur Orcs, die Stiefel wollen, und ein Junges, das ein Spielzeug will, das Lärm macht, und niemand, der auf Leinen wartet. Ich weiß nicht, was ich sagen werde. Etwas über die Stiefel, wahrscheinlich." } },
  },
  [509] = {
    start = { title = "Der Eid", { "Feldmarschall Oslight, vom Bund von Arathor. Ich bin seit vor dem Morgengrauen auf den Beinen, also bekommt Ihr die kurze Fassung." }, { "Der Eid des Bundes ist eine Zeile. Das Becken geht an das Volk von Stromgarde zurück, und die Allianz steht hinter ihm. Ich werde Euch nicht sagen, dass es jeden Tag gut läuft. Es läuft gut genug, dass ich dafür aufstehe, und die anderen von uns auch." }, { "Wenn Ihr zur Allianz gehört und eine Waffe halten könnt, gibt es im Becken einen Platz für Euch. Wozu er dient, lernt Ihr dort." } },
    friendly = { title = "Straßen", { "Ihr wart also im Becken und habt einen Vorgeschmack bekommen, wofür es da ist." }, { "Wir kämpfen um das, was das Land tragen kann. Jeder Punkt, den der Bund hält, ist eine Straße, die zur Front offen ist, mit etwas darauf, das zu einem Heer hinaufgeht, das es braucht. Jeder Punkt, den der Feind hält, ist eine Straße, die verschlossen ist, und dieselben Dinge gehen in die andere Richtung." }, { "Die Karren rollen dieser Tage in unsere Richtung. Die Rüstmeister haben es vor mir bemerkt. Sie sind die Ersten, die wissen, wenn ein Karren zu spät ist, also sind sie auch die Ersten, die wissen, wenn er es nicht ist." }, { "Macht weiter so. Der Bund braucht Kämpfer, die verstehen, dass das Halten eines Sägewerks so viel zählen kann wie der Sieg in einem Zweikampf. Die meisten lernen es auf die harte Tour. Ein paar lernen es nie, und ich schreibe ihren Familien." } },
    honored = { title = "Stromgarde", { "Ich komme aus Stromgarde." }, { "Stromgarde hatte die besten Mauern, auf denen ich je stand, und einen König, dessen Banner ich überallhin gefolgt wäre. Ich diente dort als junger Mann, auf diesen Mauern. Ich kannte jeden Stein meines Abschnitts, und welche wackelten." }, { "Ein paar der Unseren halten sich noch in dem, was davon übrig ist. Das Syndikat hat die Festung, als hätte es für sie bezahlt, und die Oger haben sich eine Ecke der Stadt genommen. Der Rest des Volkes ist verstreut: manche hier, manche in den Straßen von Stormwind, manche irgendwo, das ich nicht nennen kann. Als der Bund seinen Eid leistete, leistete er ihn für sie." }, { "Ich erwarte nicht, Stromgarde wieder ganz zu sehen. Ich bin zu alt, und die Mauern sind zu sehr verfallen. Aber jeder Karren, der das Becken unter unserem Banner verlässt, ernährt jemanden, der diese Festung einst sein Zuhause nannte." } },
    revered = { title = "Gönner", { "Stormwind bezahlt uns. Das ist kein Geheimnis. Die Münzen, die Waffen, die Pferde, das Brot: der Geldbeutel unserer Gönner." }, { "Was die Gönner dafür erwarten, darüber habe ich meine Vermutungen. Ich habe gesehen, wie Urkunden unterzeichnet werden, von Männern, die nie im Regen in Arathi standen, und ich glaube nicht, dass die Leute, die hier vor dem Krieg Landwirtschaft betrieben, ihre Felder so zurückbekommen, wie sie sie hatten. Manche dieser Familien sind hier in der Zuflucht und flicken die Stiefel meiner Soldaten, und sie fragen mich nicht danach." }, { "Damit habe ich meinen Frieden gemacht, größtenteils. Ein Hof ernährt Menschen, wer auch immer die Urkunde hält. Das Volk von Stromgarde wird so oder so davon essen, und das habe ich geschworen." }, { "Also kämpft für die Leute, die von diesen Höfen essen werden, und überlasst die Urkunden den Männern, die sie unterzeichnen. Ein Schreiber würde Euch eine hübschere Geschichte erzählen. Ich halte mich selbst an diese, an den Tagen, an denen es mir gelingt." } },
    exalted = { title = "Die Mauer", { "Ich bin einmal davongelaufen." }, { "In der Nacht, in der die Mauern von Stromgarde verloren gingen, stand ich auf ihnen. Ich hatte einen Posten und einen Hauptmann und ein Schwert, mit dem ich umzugehen wusste, und als das Tor fiel, lief ich. Den Hügel hinunter, in die Dunkelheit, und weiter, bis der Lärm hinter mir verstummte. Ich habe seitdem gesagt, die Mauer sei schon verloren gewesen, und das war sie. Ein Schwert mehr wäre ein Leichnam mehr gewesen. Ich lief, weil ich jung war und Angst hatte, und die Dunkelheit am Fuß des Hügels sich wie Leben anfühlte." }, { "Die Akte eines Feldmarschalls verzeichnet, wo er stand. Meine nennt Stromgarde und lässt den Hügel weg." }, { "Die Berichte aus dem Becken kommen jeden Abend zu mir herauf, wer hielt und wer brach. Und die Rekruten, die neben Euch einen Punkt hielten, halten auch den nächsten. Das breitet sich aus, in einem Heer. Angst breitet sich aus, und Standhalten ebenso." }, { "Sollte der Bund das Becken je endgültig halten, will ich den Hügel zur Festung hinaufgehen und als Erster auf der Mauer sein. Jemand aus Stromgarde sollte diesmal bis zum Ende auf ihr stehen, und ich wünschte, es wäre der, der davonlief." } },
  },
  [510] = {
    start = { title = "Der Name", { "Todesmeister Dwire, von den Entweihten. Die Lebenden finden den Titel beunruhigend. Ich hatte nie einen Grund, ihn zu ändern." }, { "Die Entweihten halten das Arathibecken für die Horde, oder werden es, sobald der Bund aufhört, die Sache zu bestreiten. Alles, was dieses Becken wachsen lässt oder hergibt oder fällt, kann die Horde gebrauchen. Der Bund kann es auch gebrauchen. Das ist der Streit, und ich gedenke, ihn zu gewinnen." }, { "Der Name Entweihte? Den haben wir gewählt. Der Bund hätte uns einen schlimmeren gefunden, und ich ziehe es vor, zutreffend beleidigt zu werden." }, { "Im Becken gibt es Arbeit für jeden von der Horde. Geht und verderbt einem Menschen die Ernte, dann erzählt mir davon." } },
    friendly = { title = "Bosheit", { "Zurück aus dem Becken, und der Bund ein wenig hungriger deswegen. Gut." }, { "Jeder in der Horde kämpft für etwas. Manche reden von Ehre, manche vom Land. Die Verlassenen haben auch einen Grund, und ich werde ihn Euch nicht schönreden. Bosheit." }, { "Als wir aus der Erde heraufkamen, empfingen uns die Lebenden mit Fackeln und Weihwasser. Jeden Morgen seitdem sind wir aufgestanden und haben ihnen zum Trotz weiter existiert. Es gibt keine Genugtuung wie diese." }, { "Haltet es nicht für eine Kleinigkeit. Bosheit geht nie aus. Sie braucht kein Essen, keinen Schlaf, keine Briefe von zu Hause. Ein Soldat, der für ein Zuhause kämpft, kann es verlieren. Niemandem ist es je gelungen, mir meine Bosheit zu nehmen, und der Bund hat es versucht, ausgiebig." }, { "Macht weiter so." } },
    honored = { title = "Was sie rufen", { "Die Soldaten des Bundes rufen uns über das Becken hinweg Dinge zu. Das meiste ist das Übliche: Fäulnis, Flüche, das Licht. Ab und zu sagt einer von ihnen etwas, das es wert ist, gehört zu werden." }, { "Letzte Woche am Hof rief ein junger Soldat aus Stromgarde, das Feld, das ich hielt, habe seinem Großvater gehört. Er rief es zweimal, als hätte ich es vielleicht nicht verstanden, und dann kam er damit auf mich los." }, { "Ich hielt das Feld. Dafür bin ich da. Aber der Gedanke an den alten Mann blieb danach bei mir, die ganze Nacht hindurch, und dafür bin ich ganz und gar nicht da." }, { "Also dachte ich über die Sache nach, so wie es ein Verlassener tut, wenn die Nächte lang sind. Die Menschen von Stromgarde wollen ihre Felder zurück. Sie hätten gern, dass Arathi wieder ihnen gehört, und die Vergangenheit dazu, und dass wir uns hinlegen und liegen bleiben. Nichts davon können sie haben. Das ist Bosheit, und ich werde sie behalten, Großvater hin oder her." }, { "Die Entweihten halten ihre Felder gut. Haltet sie weiter." } },
    revered = { title = "Die Wache", { "Die Orcs in Hammerfall machten Abwehrzeichen, als ich zum ersten Mal kam, die alte Sorte, wenn sie dachten, ich sähe nicht hin. Es störte mich nicht. Gegen mich haben schon Bessere Zeichen gemacht." }, { "Dann fing ein Sergeant von ihnen an, ein großer, vernarbter, fröhlicher Rohling mit einem halben Ohr, mir die ersten Nachrichten des Tages zu bringen, bevor sie sonst jemand hatte. Wer die Mine hielt. Wer die Ställe verloren hatte. Wer gefallen war, und ob er wieder aufstehen würde. Als ob ich sie vielleicht als Erster haben wollte. Das wollte ich." }, { "Die Entweihten sind keine Familie. Die Hälfte der Orcs findet, dass ich rieche, und sie haben recht. Aber wenn einer der Unseren an der Schmiede fällt, sind es Orcs und Trolle und Tauren und Verlassene, die zusammen zurückgehen, um ihn zu holen, unter denselben Pfeilen, und niemand hält inne, um zu fragen, was irgendjemand sonst ist." }, { "Letzte Nacht übernahm der Sergeant die lange Wache am Tor, damit ich den neuen Rekruten nicht erklären musste, warum ich nicht schlafe. Niemand hatte ihn darum gebeten. Er erzählte ihnen, ich sei beim Gebet. Ich ließ ihn." } },
    exalted = { title = "Die Tür", { "Ich sagte Bosheit, als Ihr neu bei uns wart. Es ist wahr, und es ist die Antwort, die ich am liebsten gebe, weil sie den Lebenden Angst macht und mich nichts kostet." }, { "Darunter gibt es eine andere." }, { "Als mein Volk nach einem Platz in der Welt suchte, war jede Tür darin gegen uns verschlossen bis auf eine, und es war die der Horde. Die Horde ließ sich Zeit mit uns. Manche der Orcs wollten nichts mit den Toten zu tun haben. Manche der Tauren sprachen trotzdem für uns, und der Kriegshäuptling hörte sie an. Niemand sonst tat es, und ich habe nicht vergessen, wer es tat." }, { "Alles, was die Entweihten aus diesem Becken nehmen, geht nach Hause, zu dem Volk, das diese Tür geöffnet hat. Das Erz geht an ihre Schmieden und das Korn an ihre Tische. Ich werde nie einen Krümel davon essen, und das ist mir recht. Diesen Grund verwahre ich unter der Bosheit, wo der Bund nicht herankommt." }, { "Ihr habt einen guten Teil dieses Beckens für das Volk hinter jener Tür gehalten. Der Bund hat es bemerkt. Ich ebenso, und der Sergeant auch." }, { "Nehmt den Dank der Entweihten. Meinen werdet Ihr zweimal von mir verlangen müssen." } },
  },
}
-- (the places Classic Era's client names otherwise, swapped in there, the longest first)
ns.classicNames = {  }
